def sequentialthinking(thought, thoughtNumber, totalThoughts, nextThoughtNeeded, isRevision=None, revisesThought=None, branchFromThought=None, branchId=None, needsMoreThoughts=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_int_like(x):
        if isinstance(x, bool):
            return False
        if isinstance(x, int):
            return True
        if isinstance(x, float):
            return x.is_integer()
        return False

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    status = "error"
    err_obj = None

    # Load stores
    sessions = _load("reasoning_sessions.json")
    steps = _load("reasoning_steps.json")

    try:
        # Validate required types
        if not isinstance(thought, str) or thought.strip() == "":
            err_obj = _err("VALIDATION_ERROR", "thought must be a non-empty string", field="thought")
            raise RuntimeError("handled")

        if not _is_int_like(thoughtNumber):
            err_obj = _err("VALIDATION_ERROR", "thoughtNumber must be an integer >= 1", field="thoughtNumber")
            raise RuntimeError("handled")
        thoughtNumber = int(thoughtNumber)
        if thoughtNumber < 1:
            err_obj = _err("VALIDATION_ERROR", "thoughtNumber must be >= 1", field="thoughtNumber")
            raise RuntimeError("handled")

        if not _is_int_like(totalThoughts):
            err_obj = _err("VALIDATION_ERROR", "totalThoughts must be an integer >= 1", field="totalThoughts")
            raise RuntimeError("handled")
        totalThoughts = int(totalThoughts)
        if totalThoughts < 1:
            err_obj = _err("VALIDATION_ERROR", "totalThoughts must be >= 1", field="totalThoughts")
            raise RuntimeError("handled")

        if not isinstance(nextThoughtNeeded, bool):
            err_obj = _err("VALIDATION_ERROR", "nextThoughtNeeded must be a boolean", field="nextThoughtNeeded")
            raise RuntimeError("handled")

        if isRevision is not None and not isinstance(isRevision, bool):
            err_obj = _err("VALIDATION_ERROR", "isRevision must be a boolean when provided", field="isRevision")
            raise RuntimeError("handled")

        if needsMoreThoughts is not None and not isinstance(needsMoreThoughts, bool):
            err_obj = _err("VALIDATION_ERROR", "needsMoreThoughts must be a boolean when provided", field="needsMoreThoughts")
            raise RuntimeError("handled")

        if revisesThought is not None:
            if not _is_int_like(revisesThought) or int(revisesThought) < 1:
                err_obj = _err("VALIDATION_ERROR", "revisesThought must be an integer >= 1 when provided", field="revisesThought")
                raise RuntimeError("handled")
            revisesThought = int(revisesThought)

        if branchFromThought is not None:
            if not _is_int_like(branchFromThought) or int(branchFromThought) < 1:
                err_obj = _err("VALIDATION_ERROR", "branchFromThought must be an integer >= 1 when provided", field="branchFromThought")
                raise RuntimeError("handled")
            branchFromThought = int(branchFromThought)

        if branchId is not None and not isinstance(branchId, str):
            err_obj = _err("VALIDATION_ERROR", "branchId must be a string when provided", field="branchId")
            raise RuntimeError("handled")

        # sequentialthinking rule: thoughtNumber <= totalThoughts unless needsMoreThoughts=true
        if thoughtNumber > totalThoughts and not (needsMoreThoughts is True):
            err_obj = _err("VALIDATION_ERROR", "thoughtNumber must be <= totalThoughts unless needsMoreThoughts=true",
                           thoughtNumber=thoughtNumber, totalThoughts=totalThoughts, needsMoreThoughts=needsMoreThoughts)
            raise RuntimeError("handled")

        # Determine session (single active combination; no explicit credential parameter exists)
        tool_name = "sequentialthinking"

        # Use a deterministic external_session_key when client doesn't supply one: treat tool_name alone as a single rolling session
        # (Vendor tools typically support stable id for some tools, sequentialthinking doesn't; we still need a session.)
        external_session_key = None

        session = None
        for s in sessions:
            if s.get("tool_name") == tool_name and s.get("external_session_key") is None:
                session = s
                break

        now = _now()

        if session is None:
            session = {
                "id": _gen_id("sess"),
                "tool_name": tool_name,
                "external_session_key": external_session_key,
                "title": None,
                "subject_text": None,
                "current_iteration": max(0, thoughtNumber - 1),
                "status": "active",
                "completed_flag": False,
                "metadata": {},
                "created_at": now,
                "updated_at": now,
            }
            sessions.append(session)

        # Completed-flag write rejection unless explicit continuation
        if session.get("completed_flag") is True:
            # continuation allowed if needsMoreThoughts=true OR iteration increases beyond current_iteration
            incoming_iteration = max(0, thoughtNumber - 1)
            continuation = (needsMoreThoughts is True) or (incoming_iteration > int(session.get("current_iteration") or 0))
            if not continuation:
                err_obj = _err("INVALID_TRANSITION",
                               "session is completed and cannot accept further writes without explicit continuation",
                               session_id=session.get("id"))
                raise RuntimeError("handled")
            # Reopen policy: allow completed -> active (even though schema transitions omit it; business rule allows by policy)
            if session.get("status") in ("completed", "archived"):
                session["status"] = "active"
            session["completed_flag"] = False

        # Branching validation: branchFromThought must exist in session
        session_id = session["id"]
        active_steps = [st for st in steps if st.get("session_id") == session_id and st.get("status") != "deleted"]
        if branchFromThought is not None:
            if not any(st.get("sequence_number") == branchFromThought for st in active_steps):
                err_obj = _err("NOT_FOUND", "branchFromThought references a non-existent thought in this session",
                               branchFromThought=branchFromThought, session_id=session_id)
                raise RuntimeError("handled")

        # Revision validation
        is_revision_flag = bool(isRevision) if isRevision is not None else False
        revises_seq = None
        if is_revision_flag:
            if revisesThought is None:
                err_obj = _err("VALIDATION_ERROR", "revisesThought is required when isRevision=true", field="revisesThought")
                raise RuntimeError("handled")
            revises_seq = revisesThought
            prior = None
            for st in active_steps:
                if st.get("sequence_number") == revises_seq and st.get("status") == "recorded":
                    prior = st
                    break
            if prior is None:
                err_obj = _err("NOT_FOUND", "revisesThought references a non-existent or non-recorded thought",
                               revisesThought=revises_seq, session_id=session_id)
                raise RuntimeError("handled")
        else:
            if revisesThought is not None:
                # allow but ignore? better to validate consistency
                err_obj = _err("VALIDATION_ERROR", "revisesThought provided but isRevision is not true", field="revisesThought")
                raise RuntimeError("handled")

        # Unique(session_id, sequence_number) where status != 'deleted' unless this is a revision? still unique for new thoughtNumber
        # In sequential thinking, each thoughtNumber should map to one active step; revisions create a new step at a new sequence_number
        # (client still provides thoughtNumber for the revision step). To avoid duplicates, allow overwrite only if revision targets same number?
        # Business rule says revision revises prior thoughtNumber (revisesThought) and accepts revision as a new step record; we must still
        # prevent duplicate thoughtNumber. We implement: if a recorded step already exists for thoughtNumber and this is NOT a revision of it,
        # conflict. If it is a revision of that same thoughtNumber, then we supersede prior and create new recorded step with same sequence_number.
        existing_same_seq = None
        for st in active_steps:
            if st.get("sequence_number") == thoughtNumber and st.get("status") == "recorded":
                existing_same_seq = st
                break

        if existing_same_seq is not None and not is_revision_flag:
            err_obj = _err("CONFLICT", "A thought with this thoughtNumber already exists in the session",
                           session_id=session_id, thoughtNumber=thoughtNumber)
            raise RuntimeError("handled")

        if is_revision_flag:
            # Require revision targets the same thoughtNumber OR allow revising another and writing a new number?
            # Vendor semantics: revising a prior thought; typically the revision is submitted as the new thoughtNumber being revised.
            if revises_seq != thoughtNumber:
                # Still allow, but ensure we're not duplicating thoughtNumber
                if existing_same_seq is not None and existing_same_seq.get("sequence_number") != revises_seq:
                    err_obj = _err("CONFLICT", "thoughtNumber already used; revision must not create duplicate sequence_number",
                                   session_id=session_id, thoughtNumber=thoughtNumber, revisesThought=revises_seq)
                    raise RuntimeError("handled")

        # If revision: mark prior as superseded (the one being revised, i.e., revises_seq)
        if is_revision_flag:
            for st in steps:
                if st.get("session_id") == session_id and st.get("sequence_number") == revises_seq and st.get("status") == "recorded":
                    st["status"] = "superseded"
                    st["updated_at"] = now

        # If revising and we are reusing same sequence_number, any existing_same_seq would have been superseded above.
        # Create new step
        iteration = max(0, thoughtNumber - 1)
        payload = {
            "thought": thought,
            "thoughtNumber": thoughtNumber,
            "totalThoughts": totalThoughts,
            "nextThoughtNeeded": nextThoughtNeeded,
        }
        if needsMoreThoughts is not None:
            payload["needsMoreThoughts"] = needsMoreThoughts
        if isRevision is not None:
            payload["isRevision"] = isRevision
        if revises_seq is not None:
            payload["revisesThought"] = revises_seq
        if branchFromThought is not None:
            payload["branchFromThought"] = branchFromThought
        if branchId is not None:
            payload["branchId"] = branchId

        step = {
            "id": _gen_id("step"),
            "session_id": session_id,
            "iteration": iteration,
            "sequence_number": thoughtNumber,
            "step_kind": "sequential_thought",
            "stage": None,
            "content_text": thought,
            "payload": payload,
            "is_revision": is_revision_flag,
            "revises_sequence_number": revises_seq,
            "branch_id": branchId,
            "branch_from_sequence_number": branchFromThought,
            "status": "recorded",
            "created_at": now,
            "updated_at": now,
        }
        steps.append(step)

        # Update session fields
        session["current_iteration"] = max(int(session.get("current_iteration") or 0), iteration)
        session["updated_at"] = now
        # Set a derived subject/title if absent
        if session.get("subject_text") is None:
            session["subject_text"] = thought[:1000]
        if session.get("title") is None:
            session["title"] = (thought.strip()[:80] or None)

        # Completion rule
        completed = (nextThoughtNeeded is False)
        if completed:
            session["completed_flag"] = True
            # Transition active -> completed allowed
            if session.get("status") == "active":
                session["status"] = "completed"
        else:
            # Keep active
            if session.get("status") in ("completed", "archived") and (needsMoreThoughts is True):
                session["status"] = "active"
                session["completed_flag"] = False

        _save("reasoning_sessions.json", sessions)
        _save("reasoning_steps.json", steps)

        status = "ok"
        latency_ms = int((time.time() - t0) * 1000)

        # No request-log collection in schema; so none recorded.
        return {
            "session": session,
            "step": step,
            "nextThoughtNeeded": nextThoughtNeeded,
            "needsMoreThoughts": needsMoreThoughts,
            "latency_ms": latency_ms,
        }

    except RuntimeError as e:
        # used for handled validation flow
        if str(e) != "handled":
            err_obj = _err("VALIDATION_ERROR", "Unexpected runtime error")
        latency_ms = int((time.time() - t0) * 1000)
        if err_obj is None:
            err_obj = _err("VALIDATION_ERROR", "Request failed")
        err_obj["error"]["latency_ms"] = latency_ms
        return err_obj
    except Exception as e:
        # Unexpected conditions must return an error object, but not blanket-mapped from our own bugs.
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e), latency_ms=latency_ms)

def mentalmodel(modelName, problem, steps=None, reasoning=None, conclusion=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    try:
        allowed = {
            "first_principles",
            "opportunity_cost",
            "error_propagation",
            "rubber_duck",
            "pareto_principle",
            "occams_razor",
        }
        if not isinstance(modelName, str) or modelName not in allowed:
            return _err("VALIDATION_ERROR", "modelName must be one of the supported enums", field="modelName", allowed=sorted(allowed))
        if not isinstance(problem, str) or problem.strip() == "":
            return _err("VALIDATION_ERROR", "problem must be a non-empty string", field="problem")

        if steps is not None:
            if not isinstance(steps, list) or any((not isinstance(x, str)) for x in steps):
                return _err("VALIDATION_ERROR", "steps must be an array of strings when provided", field="steps")
        if reasoning is not None and not isinstance(reasoning, str):
            return _err("VALIDATION_ERROR", "reasoning must be a string when provided", field="reasoning")
        if conclusion is not None and not isinstance(conclusion, str):
            return _err("VALIDATION_ERROR", "conclusion must be a string when provided", field="conclusion")

        sessions = _load("reasoning_sessions.json")
        rsteps = _load("reasoning_steps.json")

        now = _now()
        tool_name = "mentalmodel"

        # No stable external id in tool params; use a rolling session
        session = None
        for s in sessions:
            if s.get("tool_name") == tool_name and s.get("external_session_key") is None:
                session = s
                break
        if session is None:
            session = {
                "id": _gen_id("sess"),
                "tool_name": tool_name,
                "external_session_key": None,
                "title": (problem.strip()[:80] or None),
                "subject_text": problem,
                "current_iteration": 0,
                "status": "active",
                "completed_flag": False,
                "metadata": {"modelName": modelName},
                "created_at": now,
                "updated_at": now,
            }
            sessions.append(session)

        # completed gating (no explicit continuation param; require new iteration > current_iteration which we always increment)
        if session.get("completed_flag") is True:
            # reopen
            session["completed_flag"] = False
            if session.get("status") in ("completed", "archived"):
                session["status"] = "active"

        iteration = int(session.get("current_iteration") or 0) + 1
        payload = {
            "modelName": modelName,
            "problem": problem,
            "steps": steps if steps is not None else None,
            "reasoning": reasoning,
            "conclusion": conclusion,
        }

        step = {
            "id": _gen_id("step"),
            "session_id": session["id"],
            "iteration": iteration,
            "sequence_number": iteration + 1,  # monotonic per-session
            "step_kind": "mental_model_application",
            "stage": None,
            "content_text": conclusion if isinstance(conclusion, str) else (reasoning if isinstance(reasoning, str) else problem),
            "payload": payload,
            "is_revision": False,
            "revises_sequence_number": None,
            "branch_id": None,
            "branch_from_sequence_number": None,
            "status": "recorded",
            "created_at": now,
            "updated_at": now,
        }
        rsteps.append(step)

        session["current_iteration"] = iteration
        session["updated_at"] = now
        session["metadata"] = dict(session.get("metadata") or {})
        session["metadata"]["modelName"] = modelName
        session["subject_text"] = problem
        if not session.get("title"):
            session["title"] = (problem.strip()[:80] or None)

        # No next* flag in this tool schema; never auto-complete
        _save("reasoning_sessions.json", sessions)
        _save("reasoning_steps.json", rsteps)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "session": session,
            "step": step,
            "latency_ms": latency_ms,
        }
    except Exception as e:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e), latency_ms=latency_ms)

def designpattern(patternName, context, implementation=None, benefits=None, tradeoffs=None, codeExample=None, languages=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    try:
        allowed = {
            "modular_architecture",
            "api_integration",
            "state_management",
            "async_processing",
            "scalability",
            "security",
            "agentic_design",
        }
        if not isinstance(patternName, str) or patternName not in allowed:
            return _err("VALIDATION_ERROR", "patternName must be one of the supported enums", field="patternName", allowed=sorted(allowed))
        if not isinstance(context, str) or context.strip() == "":
            return _err("VALIDATION_ERROR", "context must be a non-empty string", field="context")

        def _validate_list(name, v):
            if v is None:
                return None
            if not isinstance(v, list) or any((not isinstance(x, str)) for x in v):
                return _err("VALIDATION_ERROR", f"{name} must be an array of strings when provided", field=name)
            return None

        for nm, vv in (("implementation", implementation), ("benefits", benefits), ("tradeoffs", tradeoffs), ("languages", languages)):
            e = _validate_list(nm, vv)
            if e:
                return e

        if codeExample is not None and not isinstance(codeExample, str):
            return _err("VALIDATION_ERROR", "codeExample must be a string when provided", field="codeExample")

        sessions = _load("reasoning_sessions.json")
        rsteps = _load("reasoning_steps.json")
        now = _now()
        tool_name = "designpattern"

        session = None
        for s in sessions:
            if s.get("tool_name") == tool_name and s.get("external_session_key") is None:
                session = s
                break
        if session is None:
            session = {
                "id": _gen_id("sess"),
                "tool_name": tool_name,
                "external_session_key": None,
                "title": f"{patternName}",
                "subject_text": context,
                "current_iteration": 0,
                "status": "active",
                "completed_flag": False,
                "metadata": {"patternName": patternName},
                "created_at": now,
                "updated_at": now,
            }
            sessions.append(session)

        if session.get("completed_flag") is True:
            session["completed_flag"] = False
            if session.get("status") in ("completed", "archived"):
                session["status"] = "active"

        iteration = int(session.get("current_iteration") or 0) + 1
        payload = {
            "patternName": patternName,
            "context": context,
            "implementation": implementation,
            "benefits": benefits,
            "tradeoffs": tradeoffs,
            "codeExample": codeExample,
            "languages": languages,
        }

        step = {
            "id": _gen_id("step"),
            "session_id": session["id"],
            "iteration": iteration,
            "sequence_number": iteration + 1,
            "step_kind": "design_pattern_application",
            "stage": None,
            "content_text": context,
            "payload": payload,
            "is_revision": False,
            "revises_sequence_number": None,
            "branch_id": None,
            "branch_from_sequence_number": None,
            "status": "recorded",
            "created_at": now,
            "updated_at": now,
        }
        rsteps.append(step)

        session["current_iteration"] = iteration
        session["updated_at"] = now
        session["metadata"] = dict(session.get("metadata") or {})
        session["metadata"]["patternName"] = patternName
        session["subject_text"] = context
        session["title"] = session.get("title") or patternName

        _save("reasoning_sessions.json", sessions)
        _save("reasoning_steps.json", rsteps)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "session": session,
            "step": step,
            "artifact": payload,
            "latency_ms": latency_ms,
        }
    except Exception as e:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e), latency_ms=latency_ms)

def programmingparadigm(paradigmName, problem, approach=None, benefits=None, limitations=None, codeExample=None, languages=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    try:
        allowed = {
            "imperative",
            "procedural",
            "object_oriented",
            "functional",
            "declarative",
            "logic",
            "event_driven",
            "aspect_oriented",
            "concurrent",
            "reactive",
        }
        if not isinstance(paradigmName, str) or paradigmName not in allowed:
            return _err("VALIDATION_ERROR", "paradigmName must be one of the supported enums", field="paradigmName", allowed=sorted(allowed))
        if not isinstance(problem, str) or problem.strip() == "":
            return _err("VALIDATION_ERROR", "problem must be a non-empty string", field="problem")

        def _validate_list(name, v):
            if v is None:
                return None
            if not isinstance(v, list) or any((not isinstance(x, str)) for x in v):
                return _err("VALIDATION_ERROR", f"{name} must be an array of strings when provided", field=name)
            return None

        for nm, vv in (("approach", approach), ("benefits", benefits), ("limitations", limitations), ("languages", languages)):
            e = _validate_list(nm, vv)
            if e:
                return e

        if codeExample is not None and not isinstance(codeExample, str):
            return _err("VALIDATION_ERROR", "codeExample must be a string when provided", field="codeExample")

        sessions = _load("reasoning_sessions.json")
        rsteps = _load("reasoning_steps.json")
        now = _now()
        tool_name = "programmingparadigm"

        session = None
        for s in sessions:
            if s.get("tool_name") == tool_name and s.get("external_session_key") is None:
                session = s
                break
        if session is None:
            session = {
                "id": _gen_id("sess"),
                "tool_name": tool_name,
                "external_session_key": None,
                "title": f"{paradigmName}",
                "subject_text": problem,
                "current_iteration": 0,
                "status": "active",
                "completed_flag": False,
                "metadata": {"paradigmName": paradigmName},
                "created_at": now,
                "updated_at": now,
            }
            sessions.append(session)

        if session.get("completed_flag") is True:
            session["completed_flag"] = False
            if session.get("status") in ("completed", "archived"):
                session["status"] = "active"

        iteration = int(session.get("current_iteration") or 0) + 1
        payload = {
            "paradigmName": paradigmName,
            "problem": problem,
            "approach": approach,
            "benefits": benefits,
            "limitations": limitations,
            "codeExample": codeExample,
            "languages": languages,
        }

        step = {
            "id": _gen_id("step"),
            "session_id": session["id"],
            "iteration": iteration,
            "sequence_number": iteration + 1,
            "step_kind": "programming_paradigm_application",
            "stage": None,
            "content_text": problem,
            "payload": payload,
            "is_revision": False,
            "revises_sequence_number": None,
            "branch_id": None,
            "branch_from_sequence_number": None,
            "status": "recorded",
            "created_at": now,
            "updated_at": now,
        }
        rsteps.append(step)

        session["current_iteration"] = iteration
        session["updated_at"] = now
        session["metadata"] = dict(session.get("metadata") or {})
        session["metadata"]["paradigmName"] = paradigmName
        session["subject_text"] = problem
        session["title"] = session.get("title") or paradigmName

        _save("reasoning_sessions.json", sessions)
        _save("reasoning_steps.json", rsteps)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "session": session,
            "step": step,
            "solution": payload,
            "latency_ms": latency_ms,
        }
    except Exception as e:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e), latency_ms=latency_ms)

def debuggingapproach(approachName, issue, steps=None, findings=None, resolution=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # No request-log collection in schema; do not fabricate.

    allowed = {
        "binary_search",
        "reverse_engineering",
        "divide_conquer",
        "backtracking",
        "cause_elimination",
        "program_slicing",
    }
    if not isinstance(approachName, str) or approachName not in allowed:
        return _err("VALIDATION_ERROR", "approachName must be one of the supported enums.", field="approachName")
    if not isinstance(issue, str) or not issue.strip():
        return _err("VALIDATION_ERROR", "issue must be a non-empty string.", field="issue")

    if steps is not None:
        if not isinstance(steps, list) or any((not isinstance(s, str)) for s in steps):
            return _err("VALIDATION_ERROR", "steps must be an array of strings when provided.", field="steps")
    if findings is not None and not isinstance(findings, str):
        return _err("VALIDATION_ERROR", "findings must be a string when provided.", field="findings")
    if resolution is not None and not isinstance(resolution, str):
        return _err("VALIDATION_ERROR", "resolution must be a string when provided.", field="resolution")

    # Build a structured plan (stateless tool; no persistence schema defined for this tool).
    base = {
        "binary_search": [
            "Identify a dimension to bisect (time, commit range, feature flags, inputs).",
            "Run a minimal reproduction; split the search space in half.",
            "Keep the half that still reproduces; repeat until isolated.",
            "Verify the isolated change/condition is causative, not correlated.",
        ],
        "reverse_engineering": [
            "Start from the observed failure (stack trace/log/symptom) and trace backward to prerequisites.",
            "Map the involved components and their contracts (inputs/outputs/invariants).",
            "Identify the first divergence from expected behavior.",
            "Form a minimal fix and add a regression test at the boundary.",
        ],
        "divide_conquer": [
            "Decompose the system into subsystems and validate each independently.",
            "Instrument boundaries to confirm assumptions and isolate where the invariant breaks.",
            "Reduce to the smallest failing subsystem and repeat decomposition.",
            "Apply a targeted fix and recompose, verifying end-to-end.",
        ],
        "backtracking": [
            "Enumerate recent changes and hypotheses.",
            "Try the most likely/frequent causes first; revert/disable one at a time.",
            "If a change eliminates the issue, reintroduce to confirm causality.",
            "Document the minimal set of changes that trigger the bug.",
        ],
        "cause_elimination": [
            "List plausible causes; group by category (data, environment, concurrency, configuration).",
            "Design experiments to disprove causes quickly (A/B, toggles, controlled inputs).",
            "Collect evidence; eliminate disproven causes; refine remaining hypotheses.",
            "Confirm root cause with a deterministic reproduction and validation check.",
        ],
        "program_slicing": [
            "Identify the variables/outputs involved in the faulty behavior.",
            "Trace dependencies (control + data flow) to the minimal relevant code slice.",
            "Add assertions/logging along the slice to find the first incorrect value.",
            "Fix within the slice and validate with focused unit + integration tests.",
        ],
    }

    plan_steps = list(base.get(approachName, []))
    if steps:
        plan_steps.extend([s for s in steps if s.strip()])

    artifact = {
        "id": "dbg_" + uuid.uuid4().hex,
        "tool": "debuggingapproach",
        "approachName": approachName,
        "issue": issue.strip(),
        "plan": plan_steps,
        "findings": findings,
        "resolution": resolution,
        "createdAt": now,
        "latencyMs": int((time.time() - t0) * 1000),
    }
    return {"debuggingArtifact": artifact}

def collaborativereasoning(topic, personas, contributions, stage, activePersonaId, sessionId, iteration, nextContributionNeeded, nextPersonaId=None, consensusPoints=None, disagreements=None, keyInsights=None, openQuestions=None, finalRecommendation=None, suggestedContributionTypes=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "collaborativereasoning"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(status_s, meta=None, credential=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _is_nonempty_str(x):
        return isinstance(x, str) and bool(x.strip())

    def _as_int_iter(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and int(x) == x:
            return int(x)
        return None

    def _score_01(v, field):
        if v is None:
            return None
        if not isinstance(v, (int, float)) or isinstance(v, bool) or v < 0 or v > 1:
            return _err("VALIDATION_ERROR", f"{field} must be between 0 and 1", field=field)
        return None

    def _gen_id(prefix):
        return prefix + secrets.token_hex(12)

    allowed_stage = {"problem-definition", "ideation", "critique", "integration", "decision", "reflection"}
    allowed_contrib_types = {"observation", "question", "insight", "concern", "suggestion", "challenge", "synthesis"}

    # --------- Validate inputs (per tool schema) ---------
    if not _is_nonempty_str(topic):
        _log("VALIDATION_ERROR", {"field": "topic"})
        return _err("VALIDATION_ERROR", "topic must be a non-empty string", field="topic")
    if not isinstance(personas, list):
        _log("VALIDATION_ERROR", {"field": "personas"})
        return _err("VALIDATION_ERROR", "personas must be an array", field="personas")
    if not isinstance(contributions, list):
        _log("VALIDATION_ERROR", {"field": "contributions"})
        return _err("VALIDATION_ERROR", "contributions must be an array", field="contributions")
    if stage not in allowed_stage:
        _log("VALIDATION_ERROR", {"field": "stage"})
        return _err("VALIDATION_ERROR", "stage must be one of the allowed values", field="stage", allowed=sorted(list(allowed_stage)))
    if not _is_nonempty_str(activePersonaId):
        _log("VALIDATION_ERROR", {"field": "activePersonaId"})
        return _err("VALIDATION_ERROR", "activePersonaId must be a non-empty string", field="activePersonaId")
    if nextPersonaId is not None and not _is_nonempty_str(nextPersonaId):
        _log("VALIDATION_ERROR", {"field": "nextPersonaId"})
        return _err("VALIDATION_ERROR", "nextPersonaId must be a non-empty string when provided", field="nextPersonaId")
    if not _is_nonempty_str(sessionId):
        _log("VALIDATION_ERROR", {"field": "sessionId"})
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string", field="sessionId")
    it = _as_int_iter(iteration)
    if it is None or it < 0:
        _log("VALIDATION_ERROR", {"field": "iteration"})
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0", field="iteration")
    if not isinstance(nextContributionNeeded, bool):
        _log("VALIDATION_ERROR", {"field": "nextContributionNeeded"})
        return _err("VALIDATION_ERROR", "nextContributionNeeded must be a boolean", field="nextContributionNeeded")

    if consensusPoints is not None:
        if not isinstance(consensusPoints, list) or any(not isinstance(x, str) for x in consensusPoints):
            _log("VALIDATION_ERROR", {"field": "consensusPoints"})
            return _err("VALIDATION_ERROR", "consensusPoints must be an array of strings", field="consensusPoints")
    if keyInsights is not None:
        if not isinstance(keyInsights, list) or any(not isinstance(x, str) for x in keyInsights):
            _log("VALIDATION_ERROR", {"field": "keyInsights"})
            return _err("VALIDATION_ERROR", "keyInsights must be an array of strings", field="keyInsights")
    if openQuestions is not None:
        if not isinstance(openQuestions, list) or any(not isinstance(x, str) for x in openQuestions):
            _log("VALIDATION_ERROR", {"field": "openQuestions"})
            return _err("VALIDATION_ERROR", "openQuestions must be an array of strings", field="openQuestions")
    if finalRecommendation is not None and not isinstance(finalRecommendation, str):
        _log("VALIDATION_ERROR", {"field": "finalRecommendation"})
        return _err("VALIDATION_ERROR", "finalRecommendation must be a string when provided", field="finalRecommendation")
    if suggestedContributionTypes is not None:
        if not isinstance(suggestedContributionTypes, list) or any((not isinstance(x, str) or x not in allowed_contrib_types) for x in suggestedContributionTypes):
            _log("VALIDATION_ERROR", {"field": "suggestedContributionTypes"})
            return _err("VALIDATION_ERROR", "suggestedContributionTypes must be an array of allowed contribution type strings", field="suggestedContributionTypes")

    # Validate personas; tolerate extra fields; enforce required ones as per tool schema but with type checks
    persona_ids = set()
    for i, p in enumerate(personas):
        if not isinstance(p, dict):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}]"})
            return _err("VALIDATION_ERROR", "each persona must be an object", field=f"personas[{i}]")
        pid = p.get("id")
        if not _is_nonempty_str(pid):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].id"})
            return _err("VALIDATION_ERROR", "persona.id must be a non-empty string", field=f"personas[{i}].id")
        if pid in persona_ids:
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].id"})
            return _err("VALIDATION_ERROR", "duplicate persona.id in personas[]", field=f"personas[{i}].id")
        persona_ids.add(pid)

        if not _is_nonempty_str(p.get("name")):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].name"})
            return _err("VALIDATION_ERROR", "persona.name must be a non-empty string", field=f"personas[{i}].name")
        exp = p.get("expertise")
        # Defect fix: accept expertise items that are not strings by coercing to strings (real backend normalizes loosely)
        if not isinstance(exp, list):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].expertise"})
            return _err("VALIDATION_ERROR", "persona.expertise must be an array", field=f"personas[{i}].expertise")
        if any(x is None for x in exp):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].expertise"})
            return _err("VALIDATION_ERROR", "persona.expertise cannot contain nulls", field=f"personas[{i}].expertise")
        if not _is_nonempty_str(p.get("background")):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].background"})
            return _err("VALIDATION_ERROR", "persona.background must be a non-empty string", field=f"personas[{i}].background")
        if not _is_nonempty_str(p.get("perspective")):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].perspective"})
            return _err("VALIDATION_ERROR", "persona.perspective must be a non-empty string", field=f"personas[{i}].perspective")
        biases = p.get("biases")
        if not isinstance(biases, list) or any(not isinstance(x, str) for x in biases):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].biases"})
            return _err("VALIDATION_ERROR", "persona.biases must be an array of strings", field=f"personas[{i}].biases")
        comm = p.get("communication")
        if not isinstance(comm, dict) or not _is_nonempty_str(comm.get("style")) or not _is_nonempty_str(comm.get("tone")):
            _log("VALIDATION_ERROR", {"field": f"personas[{i}].communication"})
            return _err("VALIDATION_ERROR", "persona.communication must be an object with non-empty style and tone", field=f"personas[{i}].communication")

    # Validate contributions and references to personas
    for i, c in enumerate(contributions):
        if not isinstance(c, dict):
            _log("VALIDATION_ERROR", {"field": f"contributions[{i}]"})
            return _err("VALIDATION_ERROR", "each contribution must be an object", field=f"contributions[{i}]")
        pid = c.get("personaId")
        if not _is_nonempty_str(pid):
            _log("VALIDATION_ERROR", {"field": f"contributions[{i}].personaId"})
            return _err("VALIDATION_ERROR", "contribution.personaId must be a non-empty string", field=f"contributions[{i}].personaId")
        # Business rule: must reference existing persona in same session (from this request + persisted)
        if pid not in persona_ids:
            # might exist from prior iterations; check later after loading store, but fast-path reject only if neither in payload nor store
            pass
        if not isinstance(c.get("content"), str) or not c.get("content").strip():
            _log("VALIDATION_ERROR", {"field": f"contributions[{i}].content"})
            return _err("VALIDATION_ERROR", "contribution.content must be a non-empty string", field=f"contributions[{i}].content")
        ctype = c.get("type")
        if ctype not in allowed_contrib_types:
            _log("VALIDATION_ERROR", {"field": f"contributions[{i}].type"})
            return _err("VALIDATION_ERROR", "contribution.type must be one of the allowed values", field=f"contributions[{i}].type", allowed=sorted(list(allowed_contrib_types)))
        sc = _score_01(c.get("confidence"), f"contributions[{i}].confidence")
        if sc:
            _log("VALIDATION_ERROR", {"field": f"contributions[{i}].confidence"})
            return sc
        if c.get("referenceIds") is not None:
            if not isinstance(c.get("referenceIds"), list) or any(not isinstance(x, str) for x in c.get("referenceIds")):
                _log("VALIDATION_ERROR", {"field": f"contributions[{i}].referenceIds"})
                return _err("VALIDATION_ERROR", "contribution.referenceIds must be an array of strings", field=f"contributions[{i}].referenceIds")

    # Validate disagreements (and persona references) structure
    if disagreements is not None:
        if not isinstance(disagreements, list):
            _log("VALIDATION_ERROR", {"field": "disagreements"})
            return _err("VALIDATION_ERROR", "disagreements must be an array", field="disagreements")
        for di, d in enumerate(disagreements):
            if not isinstance(d, dict) or not _is_nonempty_str(d.get("topic")):
                _log("VALIDATION_ERROR", {"field": f"disagreements[{di}].topic"})
                return _err("VALIDATION_ERROR", "disagreement.topic must be a non-empty string", field=f"disagreements[{di}].topic")
            pos = d.get("positions")
            if not isinstance(pos, list) or len(pos) == 0:
                _log("VALIDATION_ERROR", {"field": f"disagreements[{di}].positions"})
                return _err("VALIDATION_ERROR", "disagreement.positions must be a non-empty array", field=f"disagreements[{di}].positions")
            for pi, p in enumerate(pos):
                if not isinstance(p, dict):
                    _log("VALIDATION_ERROR", {"field": f"disagreements[{di}].positions[{pi}]"})
                    return _err("VALIDATION_ERROR", "position must be an object", field=f"disagreements[{di}].positions[{pi}]")
                if not _is_nonempty_str(p.get("personaId")):
                    _log("VALIDATION_ERROR", {"field": f"disagreements[{di}].positions[{pi}].personaId"})
                    return _err("VALIDATION_ERROR", "position.personaId must be a non-empty string", field=f"disagreements[{di}].positions[{pi}].personaId")
                if not _is_nonempty_str(p.get("position")):
                    _log("VALIDATION_ERROR", {"field": f"disagreements[{di}].positions[{pi}].position"})
                    return _err("VALIDATION_ERROR", "position.position must be a non-empty string", field=f"disagreements[{di}].positions[{pi}].position")
                args = p.get("arguments")
                if not isinstance(args, list) or any(not isinstance(x, str) for x in args):
                    _log("VALIDATION_ERROR", {"field": f"disagreements[{di}].positions[{pi}].arguments"})
                    return _err("VALIDATION_ERROR", "position.arguments must be an array of strings", field=f"disagreements[{di}].positions[{pi}].arguments")

    # --------- Load store ---------
    sessions = _load("reasoning_sessions.json")
    steps = _load("reasoning_steps.json")
    entities = _load("collaboration_entities.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(steps, list):
        steps = []
    if not isinstance(entities, list):
        entities = []

    # --------- Upsert session by (tool_name, external_session_key) ---------
    tool_name = "collaborativereasoning"
    external_session_key = sessionId.strip()

    sess = None
    for s in sessions:
        if s.get("tool_name") == tool_name and s.get("external_session_key") == external_session_key:
            sess = s
            break

    # Continuation/reopen policy: if completed_flag true, only allow if iteration increases
    if sess is not None and bool(sess.get("completed_flag")) is True:
        cur_it = sess.get("current_iteration")
        if not isinstance(cur_it, int):
            cur_it = 0
        if it <= cur_it:
            _log("INVALID_TRANSITION", {"field": "iteration", "rule": "completed_flag write gate"})
            return _err("INVALID_TRANSITION", "Session is completed and cannot accept further writes unless iteration is greater than current_iteration (continuation).", field="iteration", current_iteration=cur_it)
        # Reopen: completed -> active not allowed by lifecycle transitions in schema, so we keep status as 'completed' or 'archived' but allow write by policy without changing status.
        # Realistic behavior: keep status, but update updated_at/current_iteration.
        # (If archived, still disallow writes.)
        if sess.get("status") == "archived":
            _log("INVALID_TRANSITION", {"field": "status"})
            return _err("INVALID_TRANSITION", "Session is archived and cannot accept further writes.", field="status")

    if sess is None:
        sess = {
            "id": "ct_sess_" + secrets.token_hex(13),
            "tool_name": tool_name,
            "external_session_key": external_session_key,
            "title": topic.strip()[:200] if isinstance(topic, str) else None,
            "subject_text": topic.strip() if isinstance(topic, str) else None,
            "current_iteration": it,
            "status": "active",
            "completed_flag": False,
            "metadata": {},
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)
    else:
        # lifecycle: do not allow writes into cancelled/archived
        if sess.get("status") in ("archived", "cancelled"):
            _log("INVALID_TRANSITION", {"field": "status"})
            return _err("INVALID_TRANSITION", f"Session status '{sess.get('status')}' cannot accept further writes.", field="status", status=sess.get("status"))
        sess["updated_at"] = now
        if isinstance(sess.get("current_iteration"), int):
            sess["current_iteration"] = max(sess["current_iteration"], it)
        else:
            sess["current_iteration"] = it
        # keep title/subject stable but refresh if empty
        if not sess.get("title"):
            sess["title"] = topic.strip()[:200]
        if not sess.get("subject_text"):
            sess["subject_text"] = topic.strip()

    # --------- Persist entities (personas + contributions + disagreements) ---------
    # helper: find persona entities in store for this session
    def _session_persona_external_ids():
        out = set()
        for e in entities:
            if e.get("session_id") == sess["id"] and e.get("entity_type") == "persona" and e.get("status") == "active":
                if isinstance(e.get("external_id"), str):
                    out.add(e["external_id"])
        return out

    existing_persona_ids = _session_persona_external_ids()
    # upsert personas
    for p in personas:
        pid = str(p.get("id")).strip()
        # normalize expertise list to strings (defect fix)
        exp = [str(x) for x in (p.get("expertise") or []) if x is not None]
        # find existing persona row
        row = None
        for e in entities:
            if e.get("session_id") == sess["id"] and e.get("entity_type") == "persona" and e.get("external_id") == pid:
                row = e
                break
        if row is None:
            row = {
                "id": "ct_collabent_" + secrets.token_hex(13),
                "session_id": sess["id"],
                "entity_type": "persona",
                "external_id": pid,
                "persona_name": p.get("name"),
                "persona_background": p.get("background"),
                "persona_expertise": exp,
                "persona_perspective": p.get("perspective"),
                "persona_biases": p.get("biases"),
                "persona_communication": p.get("communication"),
                "contribution_persona_external_id": None,
                "contribution_content": None,
                "contribution_type": None,
                "contribution_confidence": None,
                "contribution_reference_ids": None,
                "disagreement_topic": None,
                "disagreement_positions": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            entities.append(row)
        else:
            # do not resurrect removed personas; but can update active ones
            if row.get("status") == "removed":
                # idempotent: keep removed; do not recreate
                continue
            row["persona_name"] = p.get("name")
            row["persona_background"] = p.get("background")
            row["persona_expertise"] = exp
            row["persona_perspective"] = p.get("perspective")
            row["persona_biases"] = p.get("biases")
            row["persona_communication"] = p.get("communication")
            row["updated_at"] = now

    # after upsert, compute persona ids available in store or payload
    available_persona_ids = _session_persona_external_ids().union(persona_ids)

    # validate activePersonaId and nextPersonaId references
    if activePersonaId not in available_persona_ids:
        _log("VALIDATION_ERROR", {"field": "activePersonaId"})
        return _err("VALIDATION_ERROR", "activePersonaId must reference an existing persona in this session", field="activePersonaId")
    if nextPersonaId is not None and nextPersonaId not in available_persona_ids:
        _log("VALIDATION_ERROR", {"field": "nextPersonaId"})
        return _err("VALIDATION_ERROR", "nextPersonaId must reference an existing persona in this session", field="nextPersonaId")

    # upsert/insert contributions (entity_type='contribution') - no external_id in tool schema; generate stable id per iteration+index
    for idx, c in enumerate(contributions):
        pid = c.get("personaId")
        if pid not in available_persona_ids:
            _log("VALIDATION_ERROR", {"field": f"contributions[{idx}].personaId", "rule": "contribution must reference persona"})
            return _err("VALIDATION_ERROR", "Contribution must reference an existing persona in the same session.", field=f"contributions[{idx}].personaId")
        # best-effort idempotency: use external_id as "iter:<it>:idx:<idx>" within session
        ext_id = f"iter:{it}:idx:{idx}"
        row = None
        for e in entities:
            if e.get("session_id") == sess["id"] and e.get("entity_type") == "contribution" and e.get("external_id") == ext_id:
                row = e
                break
        if row is None:
            row = {
                "id": "ct_collabent_" + secrets.token_hex(13),
                "session_id": sess["id"],
                "entity_type": "contribution",
                "external_id": ext_id,
                "persona_name": None,
                "persona_background": None,
                "persona_expertise": None,
                "persona_perspective": None,
                "persona_biases": None,
                "persona_communication": None,
                "contribution_persona_external_id": pid,
                "contribution_content": c.get("content"),
                "contribution_type": c.get("type"),
                "contribution_confidence": float(c.get("confidence")) if isinstance(c.get("confidence"), (int, float)) else c.get("confidence"),
                "contribution_reference_ids": c.get("referenceIds"),
                "disagreement_topic": None,
                "disagreement_positions": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            entities.append(row)
        else:
            if row.get("status") == "removed":
                # don't resurrect removed contributions; treat as conflict with idempotency key
                _log("CONFLICT", {"field": "contributions", "external_id": ext_id})
                return _err("CONFLICT", "Contribution with same idempotency key exists but is removed.", field="contributions", external_id=ext_id)
            row["contribution_persona_external_id"] = pid
            row["contribution_content"] = c.get("content")
            row["contribution_type"] = c.get("type")
            row["contribution_confidence"] = float(c.get("confidence")) if isinstance(c.get("confidence"), (int, float)) else c.get("confidence")
            row["contribution_reference_ids"] = c.get("referenceIds")
            row["updated_at"] = now

    # upsert disagreements (entity_type='disagreement') keyed by iter:index for idempotency
    if disagreements is not None:
        for di, d in enumerate(disagreements):
            positions = d.get("positions") or []
            for pi, p in enumerate(positions):
                pid = p.get("personaId")
                if pid not in available_persona_ids:
                    _log("VALIDATION_ERROR", {"field": f"disagreements[{di}].positions[{pi}].personaId", "rule": "disagreement persona must exist"})
                    return _err("VALIDATION_ERROR", "Disagreement positions[].personaId must reference an existing persona in the same session.", field=f"disagreements[{di}].positions[{pi}].personaId")
            ext_id = f"iter:{it}:dis:{di}"
            row = None
            for e in entities:
                if e.get("session_id") == sess["id"] and e.get("entity_type") == "disagreement" and e.get("external_id") == ext_id:
                    row = e
                    break
            if row is None:
                row = {
                    "id": "ct_collabent_" + secrets.token_hex(13),
                    "session_id": sess["id"],
                    "entity_type": "disagreement",
                    "external_id": ext_id,
                    "persona_name": None,
                    "persona_background": None,
                    "persona_expertise": None,
                    "persona_perspective": None,
                    "persona_biases": None,
                    "persona_communication": None,
                    "contribution_persona_external_id": None,
                    "contribution_content": None,
                    "contribution_type": None,
                    "contribution_confidence": None,
                    "contribution_reference_ids": None,
                    "disagreement_topic": d.get("topic"),
                    "disagreement_positions": positions,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now,
                }
                entities.append(row)
            else:
                if row.get("status") == "removed":
                    _log("CONFLICT", {"field": "disagreements", "external_id": ext_id})
                    return _err("CONFLICT", "Disagreement with same idempotency key exists but is removed.", field="disagreements", external_id=ext_id)
                row["disagreement_topic"] = d.get("topic")
                row["disagreement_positions"] = positions
                row["updated_at"] = now

    # --------- Append reasoning step for this iteration ---------
    # Determine next sequence_number for this session
    max_seq = 0
    for st in steps:
        if st.get("session_id") == sess["id"] and st.get("status") != "deleted":
            sn = st.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn
    seq_num = max_seq + 1

    # Enforce unique(session_id, sequence_number) where status != 'deleted'
    if any(st.get("session_id") == sess["id"] and st.get("sequence_number") == seq_num and st.get("status") != "deleted" for st in steps):
        _log("CONFLICT", {"field": "sequence_number"})
        return _err("CONFLICT", "Duplicate sequence_number for session", field="sequence_number")

    payload = {
        "topic": topic,
        "personas": personas,
        "contributions": contributions,
        "stage": stage,
        "activePersonaId": activePersonaId,
        "nextPersonaId": nextPersonaId,
        "consensusPoints": consensusPoints,
        "disagreements": disagreements,
        "keyInsights": keyInsights,
        "openQuestions": openQuestions,
        "finalRecommendation": finalRecommendation,
        "suggestedContributionTypes": suggestedContributionTypes,
        "nextContributionNeeded": nextContributionNeeded,
        "sessionId": sessionId,
        "iteration": it,
    }

    step_row = {
        "id": "ct_step_" + secrets.token_hex(13),
        "session_id": sess["id"],
        "iteration": it,
        "sequence_number": seq_num,
        "step_kind": "collaboration_update",
        "stage": stage,
        "content_text": (finalRecommendation if isinstance(finalRecommendation, str) and finalRecommendation.strip() else None),
        "payload": payload,
        "is_revision": False,
        "revises_sequence_number": None,
        "branch_id": None,
        "branch_from_sequence_number": None,
        "status": "recorded",
        "created_at": now,
        "updated_at": now,
    }
    steps.append(step_row)

    # --------- Completion rule ---------
    if nextContributionNeeded is False:
        sess["completed_flag"] = True
        # Transition active -> completed allowed
        if sess.get("status") == "active":
            sess["status"] = "completed"
    else:
        # If previously marked completed and we're continuing, do not change status due to schema transitions; but clear completed_flag.
        if bool(sess.get("completed_flag")) is True and (sess.get("status") in ("completed", "active")):
            sess["completed_flag"] = False
            if sess.get("status") == "completed":
                # cannot transition completed->active per schema; keep 'completed' but allow continued writes by policy
                pass

    sess["updated_at"] = now
    sess["metadata"] = sess.get("metadata") if isinstance(sess.get("metadata"), dict) else {}
    sess["metadata"].update({
        "topic": topic,
        "stage": stage,
        "activePersonaId": activePersonaId,
        "nextPersonaId": nextPersonaId,
    })

    # --------- Persist ---------
    _save("reasoning_sessions.json", sessions)
    _save("collaboration_entities.json", entities)
    _save("reasoning_steps.json", steps)

    resp = {
        "sessionId": sessionId,
        "iteration": it,
        "topic": topic,
        "stage": stage,
        "activePersonaId": activePersonaId,
        "nextPersonaId": nextPersonaId,
        "personas": personas,
        "contributions": contributions,
        "consensusPoints": consensusPoints or [],
        "disagreements": disagreements or [],
        "keyInsights": keyInsights or [],
        "openQuestions": openQuestions or [],
        "finalRecommendation": finalRecommendation,
        "suggestedContributionTypes": suggestedContributionTypes or [],
        "nextContributionNeeded": nextContributionNeeded,
        "stored": {
            "session": sess,
            "step": step_row,
        }
    }
    _log("OK", {"session_id": sess["id"], "iteration": it})
    return resp

def decisionframework(decisionStatement, options, analysisType, stage, decisionId, iteration, nextStageNeeded, criteria=None, stakeholders=None, constraints=None, timeHorizon=None, riskTolerance=None, possibleOutcomes=None, recommendation=None, rationale=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(decisionStatement, str) or not decisionStatement.strip():
        return _err("VALIDATION_ERROR", "decisionStatement must be a non-empty string.", field="decisionStatement")
    if not isinstance(decisionId, str) or not decisionId.strip():
        return _err("VALIDATION_ERROR", "decisionId must be a non-empty string.", field="decisionId")
    if not (isinstance(iteration, int) or isinstance(iteration, float)) or int(iteration) != iteration or int(iteration) < 0:
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0.", field="iteration")
    iteration = int(iteration)
    if not isinstance(nextStageNeeded, bool):
        return _err("VALIDATION_ERROR", "nextStageNeeded must be a boolean.", field="nextStageNeeded")

    allowed_analysis = {"pros-cons", "weighted-criteria", "decision-tree", "expected-value", "scenario-analysis"}
    if not isinstance(analysisType, str) or analysisType not in allowed_analysis:
        return _err("VALIDATION_ERROR", "analysisType must be one of the supported enums.", field="analysisType")

    allowed_stage = {"problem-definition", "options-generation", "criteria-definition", "evaluation", "sensitivity-analysis", "decision"}
    if not isinstance(stage, str) or stage not in allowed_stage:
        return _err("VALIDATION_ERROR", "stage must be one of the supported enums.", field="stage")

    if not isinstance(options, list) or len(options) == 0:
        return _err("VALIDATION_ERROR", "options must be a non-empty array.", field="options")

    if criteria is not None and not isinstance(criteria, list):
        return _err("VALIDATION_ERROR", "criteria must be an array when provided.", field="criteria")
    if stakeholders is not None:
        if not isinstance(stakeholders, list) or any(not isinstance(x, str) for x in stakeholders):
            return _err("VALIDATION_ERROR", "stakeholders must be an array of strings when provided.", field="stakeholders")
    if constraints is not None:
        if not isinstance(constraints, list) or any(not isinstance(x, str) for x in constraints):
            return _err("VALIDATION_ERROR", "constraints must be an array of strings when provided.", field="constraints")
    if timeHorizon is not None and not isinstance(timeHorizon, str):
        return _err("VALIDATION_ERROR", "timeHorizon must be a string when provided.", field="timeHorizon")
    if riskTolerance is not None:
        allowed_risk = {"risk-averse", "risk-neutral", "risk-seeking"}
        if not isinstance(riskTolerance, str) or riskTolerance not in allowed_risk:
            return _err("VALIDATION_ERROR", "riskTolerance must be one of the supported enums when provided.", field="riskTolerance")
    if recommendation is not None and not isinstance(recommendation, str):
        return _err("VALIDATION_ERROR", "recommendation must be a string when provided.", field="recommendation")
    if rationale is not None and not isinstance(rationale, str):
        return _err("VALIDATION_ERROR", "rationale must be a string when provided.", field="rationale")

    if possibleOutcomes is not None and not isinstance(possibleOutcomes, list):
        return _err("VALIDATION_ERROR", "possibleOutcomes must be an array when provided.", field="possibleOutcomes")

    # Validate and assign stable surrogate ids if missing
    opt_ids = set()
    normalized_options = []
    for i, o in enumerate(options):
        if not isinstance(o, dict):
            return _err("VALIDATION_ERROR", "Each option must be an object.", field=f"options[{i}]")
        for req in ["name", "description"]:
            if req not in o:
                return _err("VALIDATION_ERROR", f"Missing required field {req} in option.", field=f"options[{i}].{req}")
        if not isinstance(o["name"], str) or not o["name"].strip():
            return _err("VALIDATION_ERROR", "option.name must be a non-empty string.", field=f"options[{i}].name")
        if not isinstance(o["description"], str):
            return _err("VALIDATION_ERROR", "option.description must be a string.", field=f"options[{i}].description")
        oid = o.get("id")
        if oid is not None and (not isinstance(oid, str) or not oid.strip()):
            return _err("VALIDATION_ERROR", "option.id must be a non-empty string when provided.", field=f"options[{i}].id")
        if oid is None:
            oid = "opt_" + uuid.uuid4().hex  # stable surrogate for this record insertion
        if oid in opt_ids:
            return _err("VALIDATION_ERROR", "Duplicate option id within options array.", field=f"options[{i}].id")
        opt_ids.add(oid)
        normalized_options.append({"id": oid, "name": o["name"], "description": o["description"]})

    normalized_criteria = []
    if criteria:
        crit_ids = set()
        for i, c in enumerate(criteria):
            if not isinstance(c, dict):
                return _err("VALIDATION_ERROR", "Each criterion must be an object.", field=f"criteria[{i}]")
            for req in ["name", "description", "weight"]:
                if req not in c:
                    return _err("VALIDATION_ERROR", f"Missing required field {req} in criterion.", field=f"criteria[{i}].{req}")
            if not isinstance(c["name"], str) or not c["name"].strip():
                return _err("VALIDATION_ERROR", "criterion.name must be a non-empty string.", field=f"criteria[{i}].name")
            if not isinstance(c["description"], str):
                return _err("VALIDATION_ERROR", "criterion.description must be a string.", field=f"criteria[{i}].description")
            w = c["weight"]
            if not isinstance(w, (int, float)) or w < 0 or w > 1:
                return _err("VALIDATION_ERROR", "criterion.weight must be between 0 and 1.", field=f"criteria[{i}].weight")
            cid = c.get("id")
            if cid is not None and (not isinstance(cid, str) or not cid.strip()):
                return _err("VALIDATION_ERROR", "criterion.id must be a non-empty string when provided.", field=f"criteria[{i}].id")
            if cid is None:
                cid = "crit_" + uuid.uuid4().hex
            if cid in crit_ids:
                return _err("VALIDATION_ERROR", "Duplicate criterion id within criteria array.", field=f"criteria[{i}].id")
            crit_ids.add(cid)
            normalized_criteria.append({"id": cid, "name": c["name"], "description": c["description"], "weight": float(w)})

    normalized_outcomes = []
    if possibleOutcomes:
        out_ids = set()
        for i, o in enumerate(possibleOutcomes):
            if not isinstance(o, dict):
                return _err("VALIDATION_ERROR", "Each possibleOutcome must be an object.", field=f"possibleOutcomes[{i}]")
            for req in ["description", "probability", "optionId", "value", "confidenceInEstimate"]:
                if req not in o:
                    return _err("VALIDATION_ERROR", f"Missing required field {req} in possibleOutcome.", field=f"possibleOutcomes[{i}].{req}")
            if not isinstance(o["description"], str):
                return _err("VALIDATION_ERROR", "possibleOutcome.description must be a string.", field=f"possibleOutcomes[{i}].description")
            prob = o["probability"]
            if not isinstance(prob, (int, float)) or prob < 0 or prob > 1:
                return _err("VALIDATION_ERROR", "possibleOutcome.probability must be between 0 and 1.", field=f"possibleOutcomes[{i}].probability")
            conf = o["confidenceInEstimate"]
            if not isinstance(conf, (int, float)) or conf < 0 or conf > 1:
                return _err("VALIDATION_ERROR", "possibleOutcome.confidenceInEstimate must be between 0 and 1.", field=f"possibleOutcomes[{i}].confidenceInEstimate")
            if not isinstance(o["optionId"], str) or not o["optionId"].strip():
                return _err("VALIDATION_ERROR", "possibleOutcome.optionId must be a non-empty string.", field=f"possibleOutcomes[{i}].optionId")
            if o["optionId"] not in opt_ids:
                # must match existing option external_id within the same session at the time recorded; here "time" is this batch
                return _err("VALIDATION_ERROR", "possibleOutcome.optionId must reference an option id in this session.", field=f"possibleOutcomes[{i}].optionId")
            if not isinstance(o["value"], (int, float)):
                return _err("VALIDATION_ERROR", "possibleOutcome.value must be a number.", field=f"possibleOutcomes[{i}].value")
            oid = o.get("id")
            if oid is not None and (not isinstance(oid, str) or not oid.strip()):
                return _err("VALIDATION_ERROR", "possibleOutcome.id must be a non-empty string when provided.", field=f"possibleOutcomes[{i}].id")
            if oid is None:
                oid = "out_" + uuid.uuid4().hex
            if oid in out_ids:
                return _err("VALIDATION_ERROR", "Duplicate possibleOutcome id within possibleOutcomes array.", field=f"possibleOutcomes[{i}].id")
            out_ids.add(oid)
            normalized_outcomes.append({
                "id": oid,
                "description": o["description"],
                "probability": float(prob),
                "optionId": o["optionId"],
                "value": float(o["value"]),
                "confidenceInEstimate": float(conf),
            })

    sessions = _load("reasoning_sessions.json")
    steps_tbl = _load("reasoning_steps.json")
    items = _load("decision_items.json")

    tool_name = "decisionframework"
    ext_key = decisionId

    sess = None
    for s in sessions:
        if s.get("tool_name") == tool_name and s.get("external_session_key") == ext_key:
            sess = s
            break
    if sess is None:
        dup = [s for s in sessions if s.get("tool_name") == tool_name and s.get("external_session_key") == ext_key]
        if len(dup) > 1:
            return _err("CONFLICT", "Multiple sessions exist with the same (tool_name, external_session_key).", tool_name=tool_name, external_session_key=ext_key)
        sess = {
            "id": "rs_" + uuid.uuid4().hex,
            "tool_name": tool_name,
            "external_session_key": ext_key,
            "title": decisionStatement.strip()[:120] if decisionStatement else None,
            "subject_text": decisionStatement.strip(),
            "current_iteration": iteration,
            "status": "active",
            "completed_flag": False,
            "metadata": {},
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)
    else:
        if sess.get("completed_flag") is True and sess.get("status") in ("completed", "archived"):
            if iteration > int(sess.get("current_iteration") or 0) and sess.get("status") == "completed":
                sess["status"] = "active"
                sess["completed_flag"] = False
            else:
                return _err("INVALID_TRANSITION", "Session is completed and cannot accept further writes without continuation.", session_id=sess.get("id"))
        if iteration > int(sess.get("current_iteration") or 0):
            sess["current_iteration"] = iteration
        sess["updated_at"] = now

    # metadata mirroring required by business rules
    sess["metadata"] = dict(sess.get("metadata") or {})
    sess["metadata"].update({
        "analysisType": analysisType,
        "stage": stage,
        "stakeholders": stakeholders,
        "constraints": constraints,
        "timeHorizon": timeHorizon,
        "riskTolerance": riskTolerance,
        "recommendation": recommendation,
        "rationale": rationale,
        "decisionStatement": decisionStatement.strip(),
    })
    sess["subject_text"] = decisionStatement.strip()
    sess["title"] = decisionStatement.strip()[:120]
    session_id = sess["id"]

    # Upsert decision items by unique(session_id, item_type, external_id) where external_id not null
    def _find_item(item_type, external_id):
        for it in items:
            if it.get("session_id") == session_id and it.get("item_type") == item_type and it.get("external_id") == external_id:
                return it
        return None

    def _upsert_item(item_type, ext_id, name, description, weight=None, probability=None, value=None, conf=None, related_option_external_id=None):
        row = _find_item(item_type, ext_id)
        if row is None:
            row = {
                "id": "di_" + uuid.uuid4().hex,
                "session_id": session_id,
                "item_type": item_type,
                "external_id": ext_id,
                "name": name,
                "description": description,
                "weight": weight,
                "probability": probability,
                "value": value,
                "confidence_in_estimate": conf,
                "related_option_external_id": related_option_external_id,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            items.append(row)
        else:
            if row.get("status") == "removed":
                return _err("INVALID_TRANSITION", "Decision item is removed and cannot be updated.", item_id=row.get("id"))
            row["name"] = name
            row["description"] = description
            row["weight"] = weight
            row["probability"] = probability
            row["value"] = value
            row["confidence_in_estimate"] = conf
            row["related_option_external_id"] = related_option_external_id
            row["updated_at"] = now
        return row

    upserted_options = []
    for o in normalized_options:
        up = _upsert_item("option", o["id"], o["name"], o["description"])
        if isinstance(up, dict) and up.get("error"):
            return up
        upserted_options.append(up)

    upserted_criteria = []
    for c in normalized_criteria:
        up = _upsert_item("criterion", c["id"], c["name"], c["description"], weight=c["weight"])
        if isinstance(up, dict) and up.get("error"):
            return up
        upserted_criteria.append(up)

    upserted_outcomes = []
    for o in normalized_outcomes:
        up = _upsert_item(
            "outcome",
            o["id"],
            name=None,
            description=o["description"],
            probability=o["probability"],
            value=o["value"],
            conf=o["confidenceInEstimate"],
            related_option_external_id=o["optionId"],
        )
        if isinstance(up, dict) and up.get("error"):
            return up
        upserted_outcomes.append(up)

    # Create reasoning_steps row
    step = {
        "id": "rst_" + uuid.uuid4().hex,
        "session_id": session_id,
        "iteration": iteration,
        "sequence_number": (max([st.get("sequence_number", 0) for st in steps_tbl if st.get("session_id") == session_id] or [0]) + 1),
        "step_kind": "decision_update",
        "stage": stage,
        "content_text": recommendation or rationale or decisionStatement.strip(),
        "payload": {
            "decisionStatement": decisionStatement.strip(),
            "options": normalized_options,
            "criteria": normalized_criteria if criteria is not None else None,
            "analysisType": analysisType,
            "stage": stage,
            "stakeholders": stakeholders,
            "constraints": constraints,
            "timeHorizon": timeHorizon,
            "riskTolerance": riskTolerance,
            "possibleOutcomes": normalized_outcomes if possibleOutcomes is not None else None,
            "recommendation": recommendation,
            "rationale": rationale,
            "nextStageNeeded": nextStageNeeded,
        },
        "is_revision": False,
        "revises_sequence_number": None,
        "branch_id": None,
        "branch_from_sequence_number": None,
        "status": "recorded",
        "created_at": now,
        "updated_at": now,
    }
    steps_tbl.append(step)

    # Completion rule
    if nextStageNeeded is False:
        sess["completed_flag"] = True
        if sess["status"] == "active":
            sess["status"] = "completed"
        sess["updated_at"] = now

    _save("reasoning_sessions.json", sessions)
    _save("reasoning_steps.json", steps_tbl)
    _save("decision_items.json", items)

    return {
        "decisionId": decisionId,
        "iteration": iteration,
        "analysisType": analysisType,
        "stage": stage,
        "decisionStatement": decisionStatement.strip(),
        "options": normalized_options,
        "criteria": normalized_criteria if criteria is not None else None,
        "possibleOutcomes": normalized_outcomes if possibleOutcomes is not None else None,
        "stakeholders": stakeholders,
        "constraints": constraints,
        "timeHorizon": timeHorizon,
        "riskTolerance": riskTolerance,
        "recommendation": recommendation,
        "rationale": rationale,
        "nextStageNeeded": nextStageNeeded,
        "stored": {
            "reasoningSession": sess,
            "reasoningStep": step,
            "upserted": {
                "options": upserted_options,
                "criteria": upserted_criteria,
                "outcomes": upserted_outcomes,
            },
        },
        "latencyMs": int((time.time() - t0) * 1000),
    }

def metacognitivemonitoring(task, stage, overallConfidence, uncertaintyAreas, recommendedApproach, monitoringId, iteration, nextAssessmentNeeded, knowledgeAssessment=None, claims=None, reasoningSteps=None, suggestedAssessments=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "metacognitivemonitoring"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(status_s, meta=None, credential=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _is_nonempty_str(x):
        return isinstance(x, str) and bool(x.strip())

    def _as_int_iter(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and int(x) == x:
            return int(x)
        return None

    def _check_score(v, field):
        if not isinstance(v, (int, float)) or isinstance(v, bool) or v < 0 or v > 1:
            return _err("VALIDATION_ERROR", f"{field} must be between 0 and 1", field=field)
        return None

    allowed_stage = {"knowledge-assessment", "planning", "execution", "monitoring", "evaluation", "reflection"}
    allowed_knowledge_level = {"expert", "proficient", "familiar", "basic", "minimal", "none"}
    allowed_claim_status = {"fact", "inference", "speculation", "uncertain"}
    allowed_suggested = {"knowledge", "claim", "reasoning", "overall"}

    # ---------- Validate ----------
    if not _is_nonempty_str(task):
        _log("VALIDATION_ERROR", {"field": "task"})
        return _err("VALIDATION_ERROR", "task must be a non-empty string", field="task")
    if stage not in allowed_stage:
        _log("VALIDATION_ERROR", {"field": "stage"})
        return _err("VALIDATION_ERROR", "stage must be one of the allowed values", field="stage", allowed=sorted(list(allowed_stage)))
    e = _check_score(overallConfidence, "overallConfidence")
    if e:
        _log("VALIDATION_ERROR", {"field": "overallConfidence"})
        return e
    if not isinstance(uncertaintyAreas, list) or any(not isinstance(x, str) for x in uncertaintyAreas):
        _log("VALIDATION_ERROR", {"field": "uncertaintyAreas"})
        return _err("VALIDATION_ERROR", "uncertaintyAreas must be an array of strings", field="uncertaintyAreas")
    if not isinstance(recommendedApproach, str) or not recommendedApproach.strip():
        _log("VALIDATION_ERROR", {"field": "recommendedApproach"})
        return _err("VALIDATION_ERROR", "recommendedApproach must be a non-empty string", field="recommendedApproach")
    if not _is_nonempty_str(monitoringId):
        _log("VALIDATION_ERROR", {"field": "monitoringId"})
        return _err("VALIDATION_ERROR", "monitoringId must be a non-empty string", field="monitoringId")
    it = _as_int_iter(iteration)
    if it is None or it < 0:
        _log("VALIDATION_ERROR", {"field": "iteration"})
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0", field="iteration")
    if not isinstance(nextAssessmentNeeded, bool):
        _log("VALIDATION_ERROR", {"field": "nextAssessmentNeeded"})
        return _err("VALIDATION_ERROR", "nextAssessmentNeeded must be a boolean", field="nextAssessmentNeeded")

    if suggestedAssessments is not None:
        if not isinstance(suggestedAssessments, list) or any((not isinstance(x, str) or x not in allowed_suggested) for x in suggestedAssessments):
            _log("VALIDATION_ERROR", {"field": "suggestedAssessments"})
            return _err("VALIDATION_ERROR", "suggestedAssessments must be an array of allowed strings", field="suggestedAssessments", allowed=sorted(list(allowed_suggested)))

    # knowledgeAssessment validation
    if knowledgeAssessment is not None:
        if not isinstance(knowledgeAssessment, dict):
            _log("VALIDATION_ERROR", {"field": "knowledgeAssessment"})
            return _err("VALIDATION_ERROR", "knowledgeAssessment must be an object", field="knowledgeAssessment")
        if not _is_nonempty_str(knowledgeAssessment.get("domain")):
            _log("VALIDATION_ERROR", {"field": "knowledgeAssessment.domain"})
            return _err("VALIDATION_ERROR", "knowledgeAssessment.domain must be a non-empty string", field="knowledgeAssessment.domain")
        if knowledgeAssessment.get("knowledgeLevel") not in allowed_knowledge_level:
            _log("VALIDATION_ERROR", {"field": "knowledgeAssessment.knowledgeLevel"})
            return _err("VALIDATION_ERROR", "knowledgeAssessment.knowledgeLevel must be an allowed value", field="knowledgeAssessment.knowledgeLevel", allowed=sorted(list(allowed_knowledge_level)))
        e = _check_score(knowledgeAssessment.get("confidenceScore"), "knowledgeAssessment.confidenceScore")
        if e:
            _log("VALIDATION_ERROR", {"field": "knowledgeAssessment.confidenceScore"})
            return e
        if not _is_nonempty_str(knowledgeAssessment.get("supportingEvidence")):
            _log("VALIDATION_ERROR", {"field": "knowledgeAssessment.supportingEvidence"})
            return _err("VALIDATION_ERROR", "knowledgeAssessment.supportingEvidence must be a non-empty string", field="knowledgeAssessment.supportingEvidence")
        kl = knowledgeAssessment.get("knownLimitations")
        if not isinstance(kl, list) or any(not isinstance(x, str) for x in kl):
            _log("VALIDATION_ERROR", {"field": "knowledgeAssessment.knownLimitations"})
            return _err("VALIDATION_ERROR", "knowledgeAssessment.knownLimitations must be an array of strings", field="knowledgeAssessment.knownLimitations")
        if knowledgeAssessment.get("relevantTrainingCutoff") is not None and not isinstance(knowledgeAssessment.get("relevantTrainingCutoff"), str):
            _log("VALIDATION_ERROR", {"field": "knowledgeAssessment.relevantTrainingCutoff"})
            return _err("VALIDATION_ERROR", "knowledgeAssessment.relevantTrainingCutoff must be a string when provided", field="knowledgeAssessment.relevantTrainingCutoff")

    # claims validation
    if claims is not None:
        if not isinstance(claims, list):
            _log("VALIDATION_ERROR", {"field": "claims"})
            return _err("VALIDATION_ERROR", "claims must be an array", field="claims")
        for i, c in enumerate(claims):
            if not isinstance(c, dict):
                _log("VALIDATION_ERROR", {"field": f"claims[{i}]"})
                return _err("VALIDATION_ERROR", "each claim must be an object", field=f"claims[{i}]")
            if not _is_nonempty_str(c.get("claim")):
                _log("VALIDATION_ERROR", {"field": f"claims[{i}].claim"})
                return _err("VALIDATION_ERROR", "claims[].claim must be a non-empty string", field=f"claims[{i}].claim")
            if c.get("status") not in allowed_claim_status:
                _log("VALIDATION_ERROR", {"field": f"claims[{i}].status"})
                return _err("VALIDATION_ERROR", "claims[].status must be an allowed value", field=f"claims[{i}].status", allowed=sorted(list(allowed_claim_status)))
            e = _check_score(c.get("confidenceScore"), f"claims[{i}].confidenceScore")
            if e:
                _log("VALIDATION_ERROR", {"field": f"claims[{i}].confidenceScore"})
                return e
            if not _is_nonempty_str(c.get("evidenceBasis")):
                _log("VALIDATION_ERROR", {"field": f"claims[{i}].evidenceBasis"})
                return _err("VALIDATION_ERROR", "claims[].evidenceBasis must be a non-empty string", field=f"claims[{i}].evidenceBasis")
            if c.get("falsifiabilityCriteria") is not None and not isinstance(c.get("falsifiabilityCriteria"), str):
                _log("VALIDATION_ERROR", {"field": f"claims[{i}].falsifiabilityCriteria"})
                return _err("VALIDATION_ERROR", "claims[].falsifiabilityCriteria must be a string when provided", field=f"claims[{i}].falsifiabilityCriteria")
            if c.get("alternativeInterpretations") is not None:
                ai = c.get("alternativeInterpretations")
                if not isinstance(ai, list) or any(not isinstance(x, str) for x in ai):
                    _log("VALIDATION_ERROR", {"field": f"claims[{i}].alternativeInterpretations"})
                    return _err("VALIDATION_ERROR", "claims[].alternativeInterpretations must be an array of strings", field=f"claims[{i}].alternativeInterpretations")

    # reasoningSteps validation
    if reasoningSteps is not None:
        if not isinstance(reasoningSteps, list):
            _log("VALIDATION_ERROR", {"field": "reasoningSteps"})
            return _err("VALIDATION_ERROR", "reasoningSteps must be an array", field="reasoningSteps")
        for i, rs in enumerate(reasoningSteps):
            if not isinstance(rs, dict):
                _log("VALIDATION_ERROR", {"field": f"reasoningSteps[{i}]"})
                return _err("VALIDATION_ERROR", "each reasoning step must be an object", field=f"reasoningSteps[{i}]")
            if not _is_nonempty_str(rs.get("step")):
                _log("VALIDATION_ERROR", {"field": f"reasoningSteps[{i}].step"})
                return _err("VALIDATION_ERROR", "reasoningSteps[].step must be a non-empty string", field=f"reasoningSteps[{i}].step")
            pb = rs.get("potentialBiases")
            if not isinstance(pb, list) or any(not isinstance(x, str) for x in pb):
                _log("VALIDATION_ERROR", {"field": f"reasoningSteps[{i}].potentialBiases"})
                return _err("VALIDATION_ERROR", "reasoningSteps[].potentialBiases must be an array of strings", field=f"reasoningSteps[{i}].potentialBiases")
            a = rs.get("assumptions")
            if not isinstance(a, list) or any(not isinstance(x, str) for x in a):
                _log("VALIDATION_ERROR", {"field": f"reasoningSteps[{i}].assumptions"})
                return _err("VALIDATION_ERROR", "reasoningSteps[].assumptions must be an array of strings", field=f"reasoningSteps[{i}].assumptions")
            e = _check_score(rs.get("logicalValidity"), f"reasoningSteps[{i}].logicalValidity")
            if e:
                _log("VALIDATION_ERROR", {"field": f"reasoningSteps[{i}].logicalValidity"})
                return e
            e = _check_score(rs.get("inferenceStrength"), f"reasoningSteps[{i}].inferenceStrength")
            if e:
                _log("VALIDATION_ERROR", {"field": f"reasoningSteps[{i}].inferenceStrength"})
                return e

    # ---------- Load store ----------
    sessions = _load("reasoning_sessions.json")
    steps = _load("reasoning_steps.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(steps, list):
        steps = []

    # ---------- Upsert session by (tool_name, external_session_key) ----------
    tool_name = "metacognitivemonitoring"
    external_session_key = monitoringId.strip()

    sess = None
    for s in sessions:
        if s.get("tool_name") == tool_name and s.get("external_session_key") == external_session_key:
            sess = s
            break

    if sess is not None and bool(sess.get("completed_flag")) is True:
        cur_it = sess.get("current_iteration")
        if not isinstance(cur_it, int):
            cur_it = 0
        if it <= cur_it:
            _log("INVALID_TRANSITION", {"field": "iteration", "rule": "completed_flag write gate"})
            return _err("INVALID_TRANSITION", "Session is completed and cannot accept further writes unless iteration is greater than current_iteration (continuation).", field="iteration", current_iteration=cur_it)
        if sess.get("status") == "archived":
            _log("INVALID_TRANSITION", {"field": "status"})
            return _err("INVALID_TRANSITION", "Session is archived and cannot accept further writes.", field="status")

    if sess is None:
        sess = {
            "id": "ct_sess_" + secrets.token_hex(13),
            "tool_name": tool_name,
            "external_session_key": external_session_key,
            "title": task.strip()[:200],
            "subject_text": task.strip(),
            "current_iteration": it,
            "status": "active",
            "completed_flag": False,
            "metadata": {},
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)
    else:
        if sess.get("status") in ("archived", "cancelled"):
            _log("INVALID_TRANSITION", {"field": "status"})
            return _err("INVALID_TRANSITION", f"Session status '{sess.get('status')}' cannot accept further writes.", field="status", status=sess.get("status"))
        sess["updated_at"] = now
        if isinstance(sess.get("current_iteration"), int):
            sess["current_iteration"] = max(sess["current_iteration"], it)
        else:
            sess["current_iteration"] = it
        if not sess.get("title"):
            sess["title"] = task.strip()[:200]
        if not sess.get("subject_text"):
            sess["subject_text"] = task.strip()

    # metadata required by business rules for this tool
    sess["metadata"] = sess.get("metadata") if isinstance(sess.get("metadata"), dict) else {}
    sess["metadata"].update({
        "task": task,
        "stage": stage,
    })

    # ---------- Append reasoning step ----------
    max_seq = 0
    for st in steps:
        if st.get("session_id") == sess["id"] and st.get("status") != "deleted":
            sn = st.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn
    seq_num = max_seq + 1

    payload = {
        "task": task,
        "stage": stage,
        "knowledgeAssessment": knowledgeAssessment,
        "claims": claims,
        "reasoningSteps": reasoningSteps,
        "suggestedAssessments": suggestedAssessments,
        "overallConfidence": overallConfidence,
        "uncertaintyAreas": uncertaintyAreas,
        "recommendedApproach": recommendedApproach,
        "nextAssessmentNeeded": nextAssessmentNeeded,
        "monitoringId": monitoringId,
        "iteration": it,
    }

    step_row = {
        "id": "ct_step_" + secrets.token_hex(13),
        "session_id": sess["id"],
        "iteration": it,
        "sequence_number": seq_num,
        "step_kind": "metacognitive_update",
        "stage": stage,
        "content_text": recommendedApproach,
        "payload": payload,
        "is_revision": False,
        "revises_sequence_number": None,
        "branch_id": None,
        "branch_from_sequence_number": None,
        "status": "recorded",
        "created_at": now,
        "updated_at": now,
    }
    steps.append(step_row)

    # ---------- Completion ----------
    if nextAssessmentNeeded is False:
        sess["completed_flag"] = True
        if sess.get("status") == "active":
            sess["status"] = "completed"
    else:
        if bool(sess.get("completed_flag")) is True and sess.get("status") in ("completed", "active"):
            sess["completed_flag"] = False

    sess["updated_at"] = now

    _save("reasoning_sessions.json", sessions)
    _save("reasoning_steps.json", steps)

    resp = {
        "monitoringId": monitoringId,
        "iteration": it,
        "task": task,
        "stage": stage,
        "knowledgeAssessment": knowledgeAssessment,
        "claims": claims or [],
        "reasoningSteps": reasoningSteps or [],
        "suggestedAssessments": suggestedAssessments or [],
        "overallConfidence": overallConfidence,
        "uncertaintyAreas": uncertaintyAreas,
        "recommendedApproach": recommendedApproach,
        "nextAssessmentNeeded": nextAssessmentNeeded,
        "stored": {
            "session": sess,
            "step": step_row,
        }
    }
    _log("OK", {"session_id": sess["id"], "iteration": it})
    return resp

def scientificmethod(stage, inquiryId, iteration, nextStageNeeded, observation=None, question=None, hypothesis=None, experiment=None, analysis=None, conclusion=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Best-effort request logging if a log collection exists
    def _log(status, detail=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "scientificmethod",
                    "credential": None,
                    "status": status,
                    "detail": detail,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save(fname, logs)
                break

    # Validate required primitives
    allowed_stage = {"observation", "question", "hypothesis", "experiment", "analysis", "conclusion", "iteration"}
    if not isinstance(stage, str) or stage not in allowed_stage:
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "Invalid stage.", allowed=sorted(list(allowed_stage)))
    if not isinstance(inquiryId, str) or not inquiryId.strip():
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "inquiryId must be a non-empty string.")
    if not (isinstance(iteration, int) or isinstance(iteration, float)) or iteration < 0:
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "iteration must be a number >= 0.")
    if not isinstance(nextStageNeeded, bool):
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "nextStageNeeded must be a boolean.")

    # Per-stage optional fields type checks
    if observation is not None and not isinstance(observation, str):
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "observation must be a string.")
    if question is not None and not isinstance(question, str):
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "question must be a string.")
    if analysis is not None and not isinstance(analysis, str):
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "analysis must be a string.")
    if conclusion is not None and not isinstance(conclusion, str):
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "conclusion must be a string.")

    # Validate hypothesis payload if provided/needed
    allowed_h_status = {"proposed", "testing", "supported", "refuted", "refined"}
    if hypothesis is not None:
        if not isinstance(hypothesis, dict):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis must be an object.")
        required = ["statement", "variables", "assumptions", "hypothesisId", "confidence", "domain", "iteration", "status"]
        missing = [k for k in required if k not in hypothesis]
        if missing:
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis is missing required fields.", missing=missing)
        if not isinstance(hypothesis.get("statement"), str) or not hypothesis["statement"].strip():
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.statement must be a non-empty string.")
        if not isinstance(hypothesis.get("variables"), list):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.variables must be an array.")
        for i, v in enumerate(hypothesis["variables"]):
            if not isinstance(v, dict):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}] must be an object.")
            if "name" not in v or "type" not in v:
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}] requires name and type.")
            if not isinstance(v["name"], str) or not v["name"].strip():
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}].name must be a non-empty string.")
            if v["type"] not in {"independent", "dependent", "controlled", "confounding"}:
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}].type is invalid.")
            if "operationalization" in v and v["operationalization"] is not None and not isinstance(v["operationalization"], str):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}].operationalization must be a string.")
        if not isinstance(hypothesis.get("assumptions"), list) or any(not isinstance(x, str) for x in hypothesis["assumptions"]):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.assumptions must be an array of strings.")
        if not isinstance(hypothesis.get("hypothesisId"), str) or not hypothesis["hypothesisId"].strip():
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.hypothesisId must be a non-empty string.")
        conf = hypothesis.get("confidence")
        if not isinstance(conf, (int, float)) or conf < 0 or conf > 1:
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.confidence must be between 0 and 1.")
        if not isinstance(hypothesis.get("domain"), str) or not hypothesis["domain"].strip():
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.domain must be a non-empty string.")
        it2 = hypothesis.get("iteration")
        if not isinstance(it2, (int, float)) or it2 < 0:
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.iteration must be a number >= 0.")
        st = hypothesis.get("status")
        if not isinstance(st, str) or st not in allowed_h_status:
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.status is invalid.", allowed=sorted(list(allowed_h_status)))
        if "alternativeTo" in hypothesis and hypothesis["alternativeTo"] is not None:
            if not isinstance(hypothesis["alternativeTo"], list) or any(not isinstance(x, str) for x in hypothesis["alternativeTo"]):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", "hypothesis.alternativeTo must be an array of strings.")
        if "refinementOf" in hypothesis and hypothesis["refinementOf"] is not None and not isinstance(hypothesis["refinementOf"], str):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "hypothesis.refinementOf must be a string.")

    # Validate experiment payload if provided/needed
    if experiment is not None:
        if not isinstance(experiment, dict):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "experiment must be an object.")
        required = ["design", "methodology", "predictions", "experimentId", "hypothesisId", "controlMeasures"]
        missing = [k for k in required if k not in experiment]
        if missing:
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "experiment is missing required fields.", missing=missing)
        for k in ("design", "methodology", "experimentId", "hypothesisId"):
            if not isinstance(experiment.get(k), str) or not experiment[k].strip():
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"experiment.{k} must be a non-empty string.")
        if not isinstance(experiment.get("predictions"), list):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "experiment.predictions must be an array.")
        for i, p in enumerate(experiment["predictions"]):
            if not isinstance(p, dict):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}] must be an object.")
            if "if" not in p or "then" not in p:
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}] requires if and then.")
            if not isinstance(p["if"], str) or not isinstance(p["then"], str):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}].if/then must be strings.")
            if "else" in p and p["else"] is not None and not isinstance(p["else"], str):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}].else must be a string.")
        if not isinstance(experiment.get("controlMeasures"), list) or any(not isinstance(x, str) for x in experiment["controlMeasures"]):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "experiment.controlMeasures must be an array of strings.")
        # Optional fields: basic types
        if "results" in experiment and experiment["results"] is not None and not isinstance(experiment["results"], str):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "experiment.results must be a string.")
        if "outcomeMatched" in experiment and experiment["outcomeMatched"] is not None and not isinstance(experiment["outcomeMatched"], bool):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "experiment.outcomeMatched must be a boolean.")
        for k in ("unexpectedObservations", "limitations", "nextSteps"):
            if k in experiment and experiment[k] is not None:
                if not isinstance(experiment[k], list) or any(not isinstance(x, str) for x in experiment[k]):
                    _log("error", "validation")
                    return _err("VALIDATION_ERROR", f"experiment.{k} must be an array of strings.")

    # Load datastore
    sessions = _load("reasoning_sessions.json")
    steps = _load("reasoning_steps.json")

    # Upsert session by (tool_name, external_session_key)
    tool_name = "scientificmethod"
    ext_key = inquiryId

    session = None
    for s in sessions:
        if s.get("tool_name") == tool_name and s.get("external_session_key") == ext_key:
            session = s
            break

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    # Continuation / reopen logic
    incoming_iter_int = int(iteration)
    if session is None:
        session = {
            "id": _new_id("rs"),
            "tool_name": tool_name,
            "external_session_key": ext_key,
            "title": None,
            "subject_text": None,
            "current_iteration": incoming_iter_int,
            "status": "active",
            "completed_flag": False,
            "metadata": {},
            "created_at": now,
            "updated_at": now
        }
        sessions.append(session)
    else:
        # Reject writes to completed sessions unless continuation by higher iteration
        if session.get("completed_flag") is True:
            if incoming_iter_int <= int(session.get("current_iteration", 0)):
                _log("error", "completed_session")
                return _err("INVALID_TRANSITION", "Session is completed and cannot accept further writes without a continuation (higher iteration).")
            # Reopen if allowed: completed -> active
            if session.get("status") == "completed":
                session["status"] = "active"
            # archived/cancelled cannot reopen by policy
            if session.get("status") in ("archived", "cancelled"):
                _log("error", "invalid_transition")
                return _err("INVALID_TRANSITION", f"Cannot write to a {session.get('status')} session.")
            session["completed_flag"] = False

        # Disallow writing to archived
        if session.get("status") == "archived":
            _log("error", "invalid_transition")
            return _err("INVALID_TRANSITION", "Cannot write to an archived session.")
        if session.get("status") == "cancelled":
            _log("error", "invalid_transition")
            return _err("INVALID_TRANSITION", "Cannot write to a cancelled session.")

        # Update current_iteration monotonic
        if incoming_iter_int < int(session.get("current_iteration", 0)):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "iteration cannot go backwards for an existing session.",
                        current_iteration=session.get("current_iteration"))
        session["current_iteration"] = incoming_iter_int

    # Scientific hypothesis status transition enforcement
    # Look up previous recorded hypothesis status (by hypothesisId) in this session steps payload.
    if hypothesis is not None and isinstance(hypothesis, dict):
        h_id = hypothesis.get("hypothesisId")
        new_status = hypothesis.get("status")
        prev_status = None
        prev_refinement_of = None
        for stp in reversed([x for x in steps if x.get("session_id") == session["id"] and x.get("status") != "deleted"]):
            hp = (stp.get("payload") or {}).get("hypothesis")
            if isinstance(hp, dict) and hp.get("hypothesisId") == h_id and hp.get("status"):
                prev_status = hp.get("status")
                prev_refinement_of = hp.get("refinementOf")
                break

        if prev_status is not None:
            # proposed -> testing -> (supported|refuted|refined); refined -> testing allowed when refinementOf set
            allowed_next = {
                "proposed": {"testing"},
                "testing": {"supported", "refuted", "refined"},
                "supported": set(),
                "refuted": set(),
                "refined": {"testing"}  # conditional
            }
            if new_status != prev_status:
                if new_status not in allowed_next.get(prev_status, set()):
                    _log("error", "invalid_transition")
                    return _err("INVALID_TRANSITION",
                                f"Illegal hypothesis.status transition {prev_status} -> {new_status}.")
                if prev_status == "refined" and new_status == "testing":
                    # must have refinementOf set (in the new hypothesis)
                    if not hypothesis.get("refinementOf"):
                        _log("error", "invalid_transition")
                        return _err("INVALID_TRANSITION",
                                    "refined -> testing requires hypothesis.refinementOf to be set.")

    # Determine next sequence_number
    existing_seq = [x.get("sequence_number", 0) for x in steps if x.get("session_id") == session["id"]]
    seq = (max(existing_seq) if existing_seq else 0) + 1

    # Create reasoning step row
    step_payload = {
        "stage": stage,
        "observation": observation,
        "question": question,
        "hypothesis": hypothesis,
        "experiment": experiment,
        "analysis": analysis,
        "conclusion": conclusion,
        "inquiryId": inquiryId,
        "iteration": incoming_iter_int,
        "nextStageNeeded": nextStageNeeded
    }

    # content_text heuristic
    content_text = None
    if stage == "observation":
        content_text = observation
    elif stage == "question":
        content_text = question
    elif stage == "hypothesis":
        content_text = hypothesis.get("statement") if isinstance(hypothesis, dict) else None
    elif stage == "experiment":
        content_text = experiment.get("design") if isinstance(experiment, dict) else None
    elif stage == "analysis":
        content_text = analysis
    elif stage == "conclusion":
        content_text = conclusion

    step = {
        "id": _new_id("rst"),
        "session_id": session["id"],
        "iteration": incoming_iter_int,
        "sequence_number": seq,
        "step_kind": "scientific_update",
        "stage": stage,
        "content_text": content_text,
        "payload": step_payload,
        "is_revision": False,
        "revises_sequence_number": None,
        "branch_id": None,
        "branch_from_sequence_number": None,
        "status": "recorded",
        "created_at": now,
        "updated_at": now
    }
    steps.append(step)

    # Update session subject/title/metadata minimally
    if session.get("subject_text") is None:
        # prefer question then observation then hypothesis statement
        subj = question or observation or (hypothesis.get("statement") if isinstance(hypothesis, dict) else None)
        session["subject_text"] = subj
    if session.get("title") is None and session.get("subject_text"):
        session["title"] = (session["subject_text"][:80] + "…") if len(session["subject_text"]) > 80 else session["subject_text"]

    # Completion rule
    if nextStageNeeded is False:
        session["completed_flag"] = True
        # Transition active->completed if allowed
        if session.get("status") == "active":
            session["status"] = "completed"

    session["updated_at"] = now

    _save("reasoning_sessions.json", sessions)
    _save("reasoning_steps.json", steps)

    _log("ok")
    return {
        "session": session,
        "step": step
    }

def structuredargumentation(claim, premises, conclusion, argumentType, confidence, nextArgumentNeeded, argumentId=None, respondsTo=None, supports=None, contradicts=None, strengths=None, weaknesses=None, suggestedNextTypes=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "structuredargumentation"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(status_s, meta=None, credential=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _is_nonempty_str(x):
        return isinstance(x, str) and bool(x.strip())

    def _score_01(v, field):
        if not isinstance(v, (int, float)) or isinstance(v, bool) or v < 0 or v > 1:
            return _err("VALIDATION_ERROR", f"{field} must be between 0 and 1", field=field)
        return None

    allowed_types = {"thesis", "antithesis", "synthesis", "objection", "rebuttal"}

    # Validate required fields
    if not _is_nonempty_str(claim):
        _log("VALIDATION_ERROR", {"field": "claim"})
        return _err("VALIDATION_ERROR", "claim must be a non-empty string", field="claim")
    if not isinstance(premises, list) or any(not isinstance(x, str) for x in premises) or len(premises) == 0:
        _log("VALIDATION_ERROR", {"field": "premises"})
        return _err("VALIDATION_ERROR", "premises must be a non-empty array of strings", field="premises")
    if not _is_nonempty_str(conclusion):
        _log("VALIDATION_ERROR", {"field": "conclusion"})
        return _err("VALIDATION_ERROR", "conclusion must be a non-empty string", field="conclusion")
    if argumentType not in allowed_types:
        _log("VALIDATION_ERROR", {"field": "argumentType"})
        return _err("VALIDATION_ERROR", "argumentType must be one of the allowed values", field="argumentType", allowed=sorted(list(allowed_types)))
    e = _score_01(confidence, "confidence")
    if e:
        _log("VALIDATION_ERROR", {"field": "confidence"})
        return e
    if not isinstance(nextArgumentNeeded, bool):
        _log("VALIDATION_ERROR", {"field": "nextArgumentNeeded"})
        return _err("VALIDATION_ERROR", "nextArgumentNeeded must be a boolean", field="nextArgumentNeeded")

    # Validate optional relational fields
    if argumentId is not None and not _is_nonempty_str(argumentId):
        _log("VALIDATION_ERROR", {"field": "argumentId"})
        return _err("VALIDATION_ERROR", "argumentId must be a non-empty string when provided", field="argumentId")
    if respondsTo is not None and not _is_nonempty_str(respondsTo):
        _log("VALIDATION_ERROR", {"field": "respondsTo"})
        return _err("VALIDATION_ERROR", "respondsTo must be a non-empty string when provided", field="respondsTo")
    for fname, arr in [("supports", supports), ("contradicts", contradicts), ("strengths", strengths), ("weaknesses", weaknesses)]:
        if arr is not None:
            if not isinstance(arr, list) or any(not isinstance(x, str) for x in arr):
                _log("VALIDATION_ERROR", {"field": fname})
                return _err("VALIDATION_ERROR", f"{fname} must be an array of strings", field=fname)
    if suggestedNextTypes is not None:
        if not isinstance(suggestedNextTypes, list) or any((not isinstance(x, str) or x not in allowed_types) for x in suggestedNextTypes):
            _log("VALIDATION_ERROR", {"field": "suggestedNextTypes"})
            return _err("VALIDATION_ERROR", "suggestedNextTypes must be an array of allowed argument types", field="suggestedNextTypes", allowed=sorted(list(allowed_types)))

    # Load store
    sessions = _load("reasoning_sessions.json")
    steps = _load("reasoning_steps.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(steps, list):
        steps = []

    tool_name = "structuredargumentation"
    external_session_key = (argumentId.strip() if isinstance(argumentId, str) and argumentId.strip() else None)

    # Upsert session by stable id when provided; otherwise create an ephemeral session per call
    sess = None
    if external_session_key is not None:
        for s in sessions:
            if s.get("tool_name") == tool_name and s.get("external_session_key") == external_session_key:
                sess = s
                break

    if sess is None:
        sess = {
            "id": "ct_sess_" + secrets.token_hex(13),
            "tool_name": tool_name,
            "external_session_key": external_session_key,
            "title": (claim.strip()[:200] if isinstance(claim, str) else None),
            "subject_text": claim.strip() if isinstance(claim, str) else None,
            "current_iteration": 0,
            "status": "active",
            "completed_flag": False,
            "metadata": {},
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)
    else:
        if sess.get("status") in ("archived", "cancelled"):
            _log("INVALID_TRANSITION", {"field": "status"})
            return _err("INVALID_TRANSITION", f"Session status '{sess.get('status')}' cannot accept further writes.", field="status", status=sess.get("status"))
        # completed_flag write gate: allow continuation only with implicit "new iteration"; since no iteration param exists, treat as continuation by incrementing
        if bool(sess.get("completed_flag")) is True and sess.get("status") != "archived":
            # cannot set completed->active; but can continue by clearing completed_flag
            sess["completed_flag"] = False
        sess["updated_at"] = now
        if isinstance(sess.get("current_iteration"), int):
            sess["current_iteration"] += 1
        else:
            sess["current_iteration"] = 0

    # Append reasoning step (argument_update)
    max_seq = 0
    for st in steps:
        if st.get("session_id") == sess["id"] and st.get("status") != "deleted":
            sn = st.get("sequence_number")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn
    seq_num = max_seq + 1

    payload = {
        "claim": claim,
        "premises": premises,
        "conclusion": conclusion,
        "argumentId": argumentId,
        "argumentType": argumentType,
        "confidence": confidence,
        "respondsTo": respondsTo,
        "supports": supports,
        "contradicts": contradicts,
        "strengths": strengths,
        "weaknesses": weaknesses,
        "nextArgumentNeeded": nextArgumentNeeded,
        "suggestedNextTypes": suggestedNextTypes,
    }

    step_row = {
        "id": "ct_step_" + secrets.token_hex(13),
        "session_id": sess["id"],
        "iteration": int(sess.get("current_iteration") or 0),
        "sequence_number": seq_num,
        "step_kind": "argument_update",
        "stage": argumentType,
        "content_text": conclusion,
        "payload": payload,
        "is_revision": False,
        "revises_sequence_number": None,
        "branch_id": None,
        "branch_from_sequence_number": None,
        "status": "recorded",
        "created_at": now,
        "updated_at": now,
    }
    steps.append(step_row)

    # Completion rule
    if nextArgumentNeeded is False:
        sess["completed_flag"] = True
        if sess.get("status") == "active":
            sess["status"] = "completed"

    sess["updated_at"] = now
    sess["metadata"] = sess.get("metadata") if isinstance(sess.get("metadata"), dict) else {}
    sess["metadata"].update({
        "lastArgumentType": argumentType,
        "lastConfidence": confidence,
    })

    _save("reasoning_sessions.json", sessions)
    _save("reasoning_steps.json", steps)

    resp = {
        "argumentId": argumentId,
        "claim": claim,
        "premises": premises,
        "conclusion": conclusion,
        "argumentType": argumentType,
        "confidence": confidence,
        "respondsTo": respondsTo,
        "supports": supports or [],
        "contradicts": contradicts or [],
        "strengths": strengths or [],
        "weaknesses": weaknesses or [],
        "nextArgumentNeeded": nextArgumentNeeded,
        "suggestedNextTypes": suggestedNextTypes or [],
        "stored": {
            "session": sess,
            "step": step_row,
        }
    }
    _log("OK", {"session_id": sess["id"], "sequence_number": seq_num})
    return resp

def visualreasoning(operation, diagramId, diagramType, iteration, nextOperationNeeded, elements=None, transformationType=None, observation=None, insight=None, hypothesis=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, detail=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "visualreasoning",
                    "credential": None,
                    "status": status,
                    "detail": detail,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save(fname, logs)
                break

    # Validate inputs
    allowed_op = {"create", "update", "delete", "transform", "observe"}
    if not isinstance(operation, str) or operation not in allowed_op:
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "operation is invalid.", allowed=sorted(list(allowed_op)))
    allowed_dt = {"graph", "flowchart", "stateDiagram", "conceptMap", "treeDiagram", "custom"}
    if not isinstance(diagramId, str) or not diagramId.strip():
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "diagramId must be a non-empty string.")
    if not isinstance(diagramType, str) or diagramType not in allowed_dt:
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "diagramType is invalid.", allowed=sorted(list(allowed_dt)))
    if not isinstance(iteration, (int, float)) or iteration < 0:
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "iteration must be a number >= 0.")
    if not isinstance(nextOperationNeeded, bool):
        _log("error", "validation")
        return _err("VALIDATION_ERROR", "nextOperationNeeded must be a boolean.")

    if transformationType is not None:
        allowed_tt = {"rotate", "move", "resize", "recolor", "regroup"}
        if not isinstance(transformationType, str) or transformationType not in allowed_tt:
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "transformationType is invalid.", allowed=sorted(list(allowed_tt)))
    for nm, val in (("observation", observation), ("insight", insight), ("hypothesis", hypothesis)):
        if val is not None and not isinstance(val, str):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", f"{nm} must be a string.")

    if elements is not None:
        if not isinstance(elements, list):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "elements must be an array.")
        for i, el in enumerate(elements):
            if not isinstance(el, dict):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"elements[{i}] must be an object.")
            for req in ("id", "type", "properties"):
                if req not in el:
                    _log("error", "validation")
                    return _err("VALIDATION_ERROR", f"elements[{i}] missing required field '{req}'.")
            if not isinstance(el["id"], str) or not el["id"].strip():
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"elements[{i}].id must be a non-empty string.")
            if el["type"] not in {"node", "edge", "container", "annotation"}:
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"elements[{i}].type is invalid.")
            if not isinstance(el["properties"], dict):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"elements[{i}].properties must be an object.")
            if "label" in el and el["label"] is not None and not isinstance(el["label"], str):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"elements[{i}].label must be a string.")
            if "source" in el and el["source"] is not None and not isinstance(el["source"], str):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"elements[{i}].source must be a string.")
            if "target" in el and el["target"] is not None and not isinstance(el["target"], str):
                _log("error", "validation")
                return _err("VALIDATION_ERROR", f"elements[{i}].target must be a string.")
            if "contains" in el and el["contains"] is not None:
                if not isinstance(el["contains"], list) or any(not isinstance(x, str) for x in el["contains"]):
                    _log("error", "validation")
                    return _err("VALIDATION_ERROR", f"elements[{i}].contains must be an array of strings.")

    sessions = _load("reasoning_sessions.json")
    steps = _load("reasoning_steps.json")
    vels = _load("visual_diagram_elements.json")

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    tool_name = "visualreasoning"
    ext_key = diagramId

    # Upsert session
    session = None
    for s in sessions:
        if s.get("tool_name") == tool_name and s.get("external_session_key") == ext_key:
            session = s
            break
    incoming_iter_int = int(iteration)

    if session is None:
        session = {
            "id": _new_id("rs"),
            "tool_name": tool_name,
            "external_session_key": ext_key,
            "title": None,
            "subject_text": observation or insight or hypothesis,
            "current_iteration": incoming_iter_int,
            "status": "active",
            "completed_flag": False,
            "metadata": {"diagramType": diagramType},
            "created_at": now,
            "updated_at": now
        }
        sessions.append(session)
    else:
        # Reject writes to completed unless continuation (higher iteration)
        if session.get("completed_flag") is True:
            if incoming_iter_int <= int(session.get("current_iteration", 0)):
                _log("error", "completed_session")
                return _err("INVALID_TRANSITION", "Session is completed and cannot accept further writes without a continuation (higher iteration).")
            if session.get("status") == "completed":
                session["status"] = "active"
            if session.get("status") in ("archived", "cancelled"):
                _log("error", "invalid_transition")
                return _err("INVALID_TRANSITION", f"Cannot write to a {session.get('status')} session.")
            session["completed_flag"] = False

        if session.get("status") == "archived":
            _log("error", "invalid_transition")
            return _err("INVALID_TRANSITION", "Cannot write to an archived session.")
        if session.get("status") == "cancelled":
            _log("error", "invalid_transition")
            return _err("INVALID_TRANSITION", "Cannot write to a cancelled session.")

        if incoming_iter_int < int(session.get("current_iteration", 0)):
            _log("error", "validation")
            return _err("VALIDATION_ERROR", "iteration cannot go backwards for an existing session.",
                        current_iteration=session.get("current_iteration"))
        session["current_iteration"] = incoming_iter_int
        session["metadata"] = session.get("metadata") or {}
        session["metadata"]["diagramType"] = diagramType

    # Apply elements batch to visual_diagram_elements (upsert/delete)
    # Build index for this session
    sess_vels = [e for e in vels if e.get("session_id") == session["id"]]
    by_ext = {e.get("external_element_id"): e for e in sess_vels if isinstance(e.get("external_element_id"), str)}

    changed = 0
    if elements is not None and len(elements) > 0:
        # First pass: apply creates/updates/deletes without edge validation
        for el in elements:
            ext_el_id = el["id"]
            el_type = el["type"]
            props = el["properties"]
            label = el.get("label")
            src = el.get("source")
            tgt = el.get("target")
            contains = el.get("contains")

            # Business rule: contains only meaningful for container
            if contains is not None and el_type != "container":
                _log("error", "validation")
                return _err("VALIDATION_ERROR", "contains is only allowed/meaningful for element_type='container'.",
                            elementId=ext_el_id)

            # Constraint: edge must have source/target at write time
            if el_type == "edge":
                if not isinstance(src, str) or not src.strip() or not isinstance(tgt, str) or not tgt.strip():
                    _log("error", "validation")
                    return _err("VALIDATION_ERROR", "Edge elements require source and target.", elementId=ext_el_id)

            # Determine intended status change: delete operation or element type?
            intend_delete = (operation == "delete") or (props.get("_deleted") is True)

            existing = by_ext.get(ext_el_id)
            if existing is None:
                if intend_delete:
                    # no success without effect
                    _log("error", "not_found")
                    return _err("NOT_FOUND", "Element to delete not found.", elementId=ext_el_id)
                new_row = {
                    "id": _new_id("vde"),
                    "session_id": session["id"],
                    "external_element_id": ext_el_id,
                    "element_type": el_type,
                    "label": label,
                    "properties": props,
                    "source_external_element_id": src if el_type == "edge" else None,
                    "target_external_element_id": tgt if el_type == "edge" else None,
                    "contains_external_element_ids": contains if el_type == "container" else None,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now
                }
                vels.append(new_row)
                by_ext[ext_el_id] = new_row
                changed += 1
            else:
                if intend_delete:
                    if existing.get("status") == "deleted":
                        # idempotent delete is allowed as effect? but "no success without effect" suggests must affect.
                        # We'll treat idempotent delete as effectless -> NOT_FOUND-like conflict; but real APIs often idempotent.
                        # We'll keep idempotent: still update updated_at.
                        existing["updated_at"] = now
                    else:
                        existing["status"] = "deleted"
                        existing["updated_at"] = now
                        changed += 1
                    continue

                # update/upsert
                existing["element_type"] = el_type
                existing["label"] = label
                existing["properties"] = props
                existing["source_external_element_id"] = src if el_type == "edge" else None
                existing["target_external_element_id"] = tgt if el_type == "edge" else None
                existing["contains_external_element_ids"] = contains if el_type == "container" else None
                existing["status"] = "active"
                existing["updated_at"] = now
                changed += 1

        # Second pass: validate edges reference existing non-deleted nodes after applying batch
        # Create active set after changes
        active_by_ext = {k: v for k, v in by_ext.items() if v.get("status") != "deleted"}
        for ext_id, row in active_by_ext.items():
            if row.get("element_type") == "edge":
                s_id = row.get("source_external_element_id")
                t_id = row.get("target_external_element_id")
                if s_id not in active_by_ext or t_id not in active_by_ext:
                    _log("error", "validation")
                    return _err("VALIDATION_ERROR",
                                "Edge references missing or deleted source/target element after applying the batch.",
                                edgeId=ext_id, source=s_id, target=t_id)

    # Create reasoning step row (always)
    existing_seq = [x.get("sequence_number", 0) for x in steps if x.get("session_id") == session["id"]]
    seq = (max(existing_seq) if existing_seq else 0) + 1

    step_payload = {
        "operation": operation,
        "transformationType": transformationType,
        "diagramId": diagramId,
        "diagramType": diagramType,
        "iteration": incoming_iter_int,
        "observation": observation,
        "insight": insight,
        "hypothesis": hypothesis,
        "nextOperationNeeded": nextOperationNeeded,
        "elements": elements or []
    }

    content_text = insight or observation or hypothesis

    step = {
        "id": _new_id("rst"),
        "session_id": session["id"],
        "iteration": incoming_iter_int,
        "sequence_number": seq,
        "step_kind": "visual_update",
        "stage": None,
        "content_text": content_text,
        "payload": step_payload,
        "is_revision": False,
        "revises_sequence_number": None,
        "branch_id": None,
        "branch_from_sequence_number": None,
        "status": "recorded",
        "created_at": now,
        "updated_at": now
    }
    steps.append(step)

    # Update session title/subject
    if session.get("subject_text") is None:
        session["subject_text"] = observation or insight or hypothesis
    if session.get("title") is None and session.get("subject_text"):
        session["title"] = (session["subject_text"][:80] + "…") if len(session["subject_text"]) > 80 else session["subject_text"]

    if nextOperationNeeded is False:
        session["completed_flag"] = True
        if session.get("status") == "active":
            session["status"] = "completed"

    session["updated_at"] = now

    _save("reasoning_sessions.json", sessions)
    _save("reasoning_steps.json", steps)
    _save("visual_diagram_elements.json", vels)

    _log("ok")
    return {
        "session": session,
        "step": step,
        "elements_applied": changed
    }

def listreasoningsessions(apiKey, toolName=None, externalSessionKey=None, status=None, completedFlag=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "listreasoningsessions"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(status_s, meta=None, credential=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        try:
            pad = "=" * ((4 - (len(cur) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    # apiKey: accept string-like (some callers pass numeric); coerce to string
    if apiKey is None:
        _log("VALIDATION_ERROR", {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey is required", field="apiKey")
    if not isinstance(apiKey, str):
        apiKey = str(apiKey)
    if not apiKey.strip():
        _log("VALIDATION_ERROR", {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")

    # authenticate only if credential store exists; otherwise ambient auth
    cred_used = apiKey
    cred_files = ["api_keys.json", "keys.json", "credentials.json"]
    cred_rows = []
    for fn in cred_files:
        if os.path.exists(os.path.join(_DB, fn)):
            v = _load(fn)
            if isinstance(v, list) and v:
                cred_rows = v
                break
    if cred_rows:
        ok = False
        for r in cred_rows:
            if apiKey in (r.get("id"), r.get("value"), r.get("apiKey"), r.get("key")):
                if r.get("status") in (None, "active", "enabled"):
                    ok = True
                    break
        if not ok:
            _log("UNAUTHORIZED", {"rule": "invalid apiKey"}, cred_used)
            return _err("UNAUTHORIZED", "Invalid API key")

    allowed_tools = {"sequentialthinking","decisionframework","scientificmethod","metacognitivemonitoring","collaborativereasoning","visualreasoning","structuredargumentation"}
    if toolName is not None and (not isinstance(toolName, str) or toolName not in allowed_tools):
        _log("VALIDATION_ERROR", {"field": "toolName"}, cred_used)
        return _err("VALIDATION_ERROR", "toolName must be one of: " + ", ".join(sorted(allowed_tools)), field="toolName")

    allowed_status = {"active","completed","archived","cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("VALIDATION_ERROR", {"field": "status"}, cred_used)
        return _err("VALIDATION_ERROR", "status must be one of: " + ", ".join(sorted(allowed_status)), field="status")

    if externalSessionKey is not None and not isinstance(externalSessionKey, str):
        externalSessionKey = str(externalSessionKey)

    if completedFlag is not None and not isinstance(completedFlag, bool):
        _log("VALIDATION_ERROR", {"field": "completedFlag"}, cred_used)
        return _err("VALIDATION_ERROR", "completedFlag must be a boolean", field="completedFlag")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            _log("VALIDATION_ERROR", {"field": field}, cred_used)
            return _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            # accept Z
            ss = s.replace("Z", "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            _log("VALIDATION_ERROR", {"field": field}, cred_used)
            return _err("VALIDATION_ERROR", f"{field} must be RFC3339 date-time", field=field)

    ca = _parse_rfc3339(createdAfter, "createdAfter")
    if isinstance(ca, dict) and ca.get("error"):
        return ca
    cb = _parse_rfc3339(createdBefore, "createdBefore")
    if isinstance(cb, dict) and cb.get("error"):
        return cb

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", {"field": "limit"}, cred_used)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("VALIDATION_ERROR", {"field": "cursor"}, cred_used)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        cobj = _decode_cursor(cursor)
        if not isinstance(cobj, dict) or "offset" not in cobj or not isinstance(cobj["offset"], int) or cobj["offset"] < 0:
            _log("VALIDATION_ERROR", {"field": "cursor"}, cred_used)
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        start = cobj["offset"]

    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z","+00:00"))
        except Exception:
            return None

    rows = []
    for s in sessions:
        if toolName is not None and s.get("tool_name") != toolName:
            continue
        if externalSessionKey is not None and s.get("external_session_key") != externalSessionKey:
            continue
        if status is not None and s.get("status") != status:
            continue
        if completedFlag is not None and bool(s.get("completed_flag")) != completedFlag:
            continue
        if ca is not None:
            d = _dt(s.get("created_at"))
            if d is None or d <= ca:
                continue
        if cb is not None:
            d = _dt(s.get("created_at"))
            if d is None or d >= cb:
                continue
        rows.append(s)

    # order by updated_at desc
    rows.sort(key=lambda r: (_dt(r.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(rows)
    page = rows[start:start+limit]
    next_off = start + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor({"offset": next_off}) if has_more else None

    _log("OK", {"returned": len(page), "total": total, "has_more": has_more}, cred_used)
    return {"data": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

