def updatereasoningsession(apiKey, id, title=None, subjectText=None, metadata=None, status=None, completedFlag=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updatereasoningsession"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(status_s, meta=None, credential=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _is_nonempty_str(x):
        return isinstance(x, str) and bool(x.strip())

    def _find_key_row(api_key_value):
        # authenticate when a credential store exists; match by id or client-visible value (never by hash)
        for fn in ["api_keys.json", "keys.json", "credentials.json"]:
            path = os.path.join(_DB, fn)
            if not os.path.exists(path):
                continue
            rows = _load(fn)
            if not isinstance(rows, list):
                continue
            for r in rows:
                if api_key_value in (r.get("id"), r.get("value"), r.get("api_key"), r.get("key")):
                    return r
        return None

    # Validate
    if apiKey is None:
        _log("VALIDATION_ERROR", {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey is required", field="apiKey")
    if not isinstance(apiKey, str):
        apiKey = str(apiKey)
    if not apiKey.strip():
        _log("VALIDATION_ERROR", {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")

    if not _is_nonempty_str(id):
        _log("VALIDATION_ERROR", {"field": "id"}, apiKey)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    if title is not None and not isinstance(title, str):
        _log("VALIDATION_ERROR", {"field": "title"}, apiKey)
        return _err("VALIDATION_ERROR", "title must be a string when provided", field="title")
    if subjectText is not None and not isinstance(subjectText, str):
        _log("VALIDATION_ERROR", {"field": "subjectText"}, apiKey)
        return _err("VALIDATION_ERROR", "subjectText must be a string when provided", field="subjectText")
    if metadata is not None and not isinstance(metadata, dict):
        _log("VALIDATION_ERROR", {"field": "metadata"}, apiKey)
        return _err("VALIDATION_ERROR", "metadata must be an object when provided", field="metadata")
    allowed_status = {"active", "completed", "archived", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("VALIDATION_ERROR", {"field": "status"}, apiKey)
        return _err("VALIDATION_ERROR", "status must be one of: active, completed, archived, cancelled", field="status")
    if completedFlag is not None and not isinstance(completedFlag, bool):
        _log("VALIDATION_ERROR", {"field": "completedFlag"}, apiKey)
        return _err("VALIDATION_ERROR", "completedFlag must be a boolean when provided", field="completedFlag")

    # Authenticate if credential store exists, otherwise allow (ambient auth)
    key_row = _find_key_row(apiKey)
    # If a credential store exists but no key matches, unauthorized
    cred_store_exists = any(os.path.exists(os.path.join(_DB, fn)) for fn in ["api_keys.json", "keys.json", "credentials.json"])
    if cred_store_exists and key_row is None:
        _log("UNAUTHORIZED", {"reason": "invalid apiKey"}, apiKey)
        return _err("UNAUTHORIZED", "Invalid API key", field="apiKey")

    sessions = _load("reasoning_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    for r in sessions:
        if r.get("id") == id:
            sess = r
            break
    if sess is None:
        _log("NOT_FOUND", {"id": id}, apiKey)
        return _err("NOT_FOUND", "Reasoning session not found", id=id)

    old_status = sess.get("status")
    if old_status not in allowed_status:
        old_status = "active"

    transitions = {
        "active": {"completed", "archived", "cancelled"},
        "completed": {"archived"},
        "archived": set(),
        "cancelled": {"archived"},
    }

    changed = False

    # Apply mutable fields
    if title is not None and title != sess.get("title"):
        sess["title"] = title
        changed = True
    if subjectText is not None and subjectText != sess.get("subject_text"):
        sess["subject_text"] = subjectText
        changed = True
    if metadata is not None:
        if not isinstance(sess.get("metadata"), dict):
            sess["metadata"] = {}
        # merge update
        for k, v in metadata.items():
            if sess["metadata"].get(k) != v:
                sess["metadata"][k] = v
                changed = True

    # completedFlag policy: if setting true, status must be completed or archived (or remain active but write-locked later by business rule)
    if completedFlag is not None and completedFlag != sess.get("completed_flag"):
        sess["completed_flag"] = completedFlag
        changed = True
        if completedFlag is True:
            # if currently active and no explicit status given, transition to completed
            if status is None and sess.get("status") == "active":
                # legal: active -> completed
                sess["status"] = "completed"
            # if currently cancelled/archived leave as-is (terminal); if completed keep completed
        else:
            # clearing completed flag: allow only if session not archived; otherwise invalid transition
            if sess.get("status") == "archived":
                _log("INVALID_TRANSITION", {"rule": "archived is terminal"}, apiKey)
                return _err("INVALID_TRANSITION", "Cannot clear completedFlag on an archived session", rule="archived terminal")

    # Status transition
    if status is not None and status != sess.get("status"):
        cur = sess.get("status")
        if cur not in transitions:
            cur = old_status
        if status not in transitions.get(cur, set()):
            _log("INVALID_TRANSITION", {"from": cur, "to": status}, apiKey)
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}", from_status=cur, to_status=status)
        sess["status"] = status
        changed = True

    # If completed_flag true, ensure status is not cancelled (nonsensical); reject
    if sess.get("completed_flag") is True and sess.get("status") == "cancelled":
        _log("CONFLICT", {"rule": "completed_flag incompatible with cancelled"}, apiKey)
        return _err("CONFLICT", "completedFlag=true is incompatible with status='cancelled'", rule="completed_flag compatibility")

    if not changed:
        _log("NOT_FOUND", {"reason": "no changes requested"}, apiKey)
        return _err("NOT_FOUND", "No changes were applied (fields already matched current values)")

    sess["updated_at"] = now
    _save("reasoning_sessions.json", sessions)
    _log("OK", {"id": id}, apiKey)
    return {"session": sess}

