            break
    if sess is None:
        _log("NOT_FOUND", {"sessionId": sessionId}, apiKey)
        return _err("NOT_FOUND", "Reasoning session not found", sessionId=sessionId)

    if iteration is not None:
        if not isinstance(iteration, int) or iteration < 1:
            _log("VALIDATION_ERROR", {"field": "iteration"}, apiKey)
            return _err("VALIDATION_ERROR", "iteration must be an integer >= 1", field="iteration")
    allowed_status = {"recorded","superseded","deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("VALIDATION_ERROR", {"field": "status"}, apiKey)
        return _err("VALIDATION_ERROR", "status must be one of: " + ", ".join(sorted(allowed_status)), field="status")
    allowed_kind = {"sequential_thought","decision_update","scientific_update","monitoring_update","collaboration_update","visual_update","argument_update"}
    if stepKind is not None and (not isinstance(stepKind, str) or stepKind not in allowed_kind):
        _log("VALIDATION_ERROR", {"field": "stepKind"}, apiKey)
        return _err("VALIDATION_ERROR", "stepKind must be one of: " + ", ".join(sorted(allowed_kind)), field="stepKind")
    if branchId is not None and not isinstance(branchId, str):
        branchId = str(branchId)

    for f, v in (("minSequenceNumber", minSequenceNumber), ("maxSequenceNumber", maxSequenceNumber)):
        if v is not None and (not isinstance(v, int) or v < 1):
            _log("VALIDATION_ERROR", {"field": f}, apiKey)
            return _err("VALIDATION_ERROR", f"{f} must be an integer >= 1", field=f)
    if minSequenceNumber is not None and maxSequenceNumber is not None and minSequenceNumber > maxSequenceNumber:
        _log("VALIDATION_ERROR", {"field": "minSequenceNumber"}, apiKey)
        return _err("VALIDATION_ERROR", "minSequenceNumber must be <= maxSequenceNumber", field="minSequenceNumber")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log("VALIDATION_ERROR", {"field": "limit"}, apiKey)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("VALIDATION_ERROR", {"field": "cursor"}, apiKey)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        cobj = _decode_cursor(cursor)
        if not isinstance(cobj, dict) or "offset" not in cobj or not isinstance(cobj["offset"], int) or cobj["offset"] < 0:
            _log("VALIDATION_ERROR", {"field": "cursor"}, apiKey)
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        start = cobj["offset"]

    steps = _load("reasoning_steps.json")
    if not isinstance(steps, list):
        steps = []

    rows = []
    for st in steps:
        if st.get("session_id") != sessionId:
            continue
        if iteration is not None and st.get("iteration") != iteration:
            continue
        if status is not None and st.get("status") != status:
            continue
        if stepKind is not None and st.get("step_kind") != stepKind:
            continue
        if branchId is not None and st.get("branch_id") != branchId:
            continue
        sn = st.get("sequence_number")
        if minSequenceNumber is not None and isinstance(sn, int) and sn < minSequenceNumber:
            continue
        if maxSequenceNumber is not None and isinstance(sn, int) and sn > maxSequenceNumber:
            continue
        rows.append(st)

    # order by iteration then sequence_number
    rows.sort(key=lambda r: (r.get("iteration") if isinstance(r.get("iteration"), int) else 0, r.get("sequence_number") if isinstance(r.get("sequence_number"), int) else 0))

    total = len(rows)
    page = rows[start:start+limit]
    next_off = start + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor({"offset": next_off}) if has_more else None

    _log("OK", {"returned": len(page), "total": total, "has_more": has_more}, apiKey)
    return {"data": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def updatereasoningstep(apiKey, id, contentText=None, payload=None, stage=None, status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updatereasoningstep"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(status_s, meta=None, credential=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _is_nonempty_str(x):
        return isinstance(x, str) and bool(x.strip())

    # Authenticate apiKey by matching *client-visible* value or id across plausible credential collections.
    # Never compare to hashes/ciphertexts.
    def _find_credential(api_key_value):
        candidates = []
        api_key_value = str(api_key_value).strip()
        for fn in ("api_keys.json", "keys.json", "credentials.json", "apiKey.json", "tokens.json"):
            path = os.path.join(_DB, fn)
            if not os.path.exists(path):
                continue
            rows = _load(fn)
            if not isinstance(rows, list):
                continue
            for r in rows:
                if not isinstance(r, dict):
                    continue
                if api_key_value in (
                    r.get("id"),
                    r.get("value"),
                    r.get("apiKey"),
                    r.get("api_key"),
                    r.get("key"),
                    r.get("token"),
                    r.get("client_key"),
                    r.get("clientKey"),
                    r.get("public_key"),
                    r.get("publicKey"),
                ):
                    candidates.append((fn, r))
        if candidates:
            # choose an "active" one if such a field exists
            for fn, r in candidates:
                if r.get("status") in (None, "active", "enabled") and r.get("revoked") not in (True, "true"):
                    return {"source_file": fn, "row": r}
            return {"source_file": candidates[0][0], "row": candidates[0][1]}
        return None

    # Validate required
    if not _is_nonempty_str(str(apiKey) if apiKey is not None else ""):
        _log("VALIDATION_ERROR", {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")
    if not _is_nonempty_str(id):
        _log("VALIDATION_ERROR", {"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    cred = _find_credential(apiKey)
    if cred is None:
        # If no credential in store can match, unauthorized
        _log("UNAUTHORIZED", {"field": "apiKey"})
        return _err("UNAUTHORIZED", "Invalid API key", field="apiKey")

    # Validate optional fields
    if contentText is not None and not isinstance(contentText, str):
        _log("VALIDATION_ERROR", {"field": "contentText"})
        return _err("VALIDATION_ERROR", "contentText must be a string when provided", field="contentText")
    if payload is not None and not isinstance(payload, dict):
        _log("VALIDATION_ERROR", {"field": "payload"})
        return _err("VALIDATION_ERROR", "payload must be an object when provided", field="payload")
    if stage is not None and not isinstance(stage, str):
        _log("VALIDATION_ERROR", {"field": "stage"})
        return _err("VALIDATION_ERROR", "stage must be a string when provided", field="stage")
    allowed_status = {"recorded", "superseded", "deleted"}
    if status is not None and status not in allowed_status:
        _log("VALIDATION_ERROR", {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of recorded, superseded, deleted", field="status", allowed=sorted(list(allowed_status)))

    # Load steps
    steps = _load("reasoning_steps.json")
    if not isinstance(steps, list):
        steps = []

    # Find step
    step = None
    for s in steps:
        if isinstance(s, dict) and s.get("id") == id:
            step = s
            break
    if step is None:
        _log("NOT_FOUND", {"field": "id"}, credential=(cred["row"].get("id") or cred["row"].get("value")))
        return _err("NOT_FOUND", "Reasoning step not found", field="id", id=id)

    # Enforce immutable identifiers not changed: tool doesn't accept them, so ensure existing keys remain
    # Lifecycle transitions
    transitions = {
        "recorded": {"superseded", "deleted"},
        "superseded": {"deleted"},
        "deleted": set(),
    }

    # Apply updates
    mutated = False
    if contentText is not None:
        if step.get("content_text") != contentText:
            step["content_text"] = contentText
            mutated = True
    if payload is not None:
        # merge replace semantics: real API typically replaces payload
        if step.get("payload") != payload:
            step["payload"] = payload
            mutated = True
    if stage is not None:
        if step.get("stage") != stage:
            step["stage"] = stage
            mutated = True
    if status is not None:
        cur = step.get("status")
        if cur is None:
            cur = "recorded"
        if status != cur:
            if status not in transitions.get(cur, set()):
                _log("INVALID_TRANSITION", {"field": "status", "from": cur, "to": status}, credential=(cred["row"].get("id") or cred["row"].get("value")))
                return _err("INVALID_TRANSITION", f"Invalid status transition from {cur} to {status}", field="status", from_status=cur, to_status=status)
            step["status"] = status
            mutated = True

    if not mutated:
        # No success without effect: if nothing changes, treat as conflict-free idempotency? Vendor behavior: treat as success with unchanged row.
        # But contract requires no success without effect for mutations: return CONFLICT if request makes no changes.
        _log("CONFLICT", {"field": "id", "reason": "no changes"}, credential=(cred["row"].get("id") or cred["row"].get("value")))
        return _err("CONFLICT", "No changes to apply", field="id", id=id)

    step["updated_at"] = now
    _save("reasoning_steps.json", steps)

    resp = {
        "id": step.get("id"),
        "sessionId": step.get("session_id"),
        "iteration": step.get("iteration"),
        "sequenceNumber": step.get("sequence_number"),
        "stepKind": step.get("step_kind"),
        "stage": step.get("stage"),
        "contentText": step.get("content_text"),
        "payload": step.get("payload"),
        "status": step.get("status"),
        "updatedAt": step.get("updated_at"),
    }
    _log("OK", {"id": id, "updated_fields": [k for k in ("contentText", "payload", "stage", "status") if locals().get(k) is not None]}, credential=(cred["row"].get("id") or cred["row"].get("value")))
    return resp

def whoami(apiKey, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0133000" if __import__("os").path.isdir("./environment_mix/0133000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "whoami"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(status_s, meta=None, credential=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if apiKey is None:
        _log("VALIDATION_ERROR", {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey is required", field="apiKey")
    if not isinstance(apiKey, str):
        apiKey = str(apiKey)
    if not apiKey.strip():
        _log("VALIDATION_ERROR", {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")

    # Resolve credential if store exists; else ambient identity
    cred_files = ["api_keys.json", "keys.json", "credentials.json"]
    cred_file = None
    cred_rows = []
    for fn in cred_files:
        p = os.path.join(_DB, fn)
        if os.path.exists(p):
            v = _load(fn)
            if isinstance(v, list) and v:
                cred_file = fn
                cred_rows = v
                break

    cred = None
    if cred_rows:
        for r in cred_rows:
            if apiKey in (r.get("id"), r.get("value"), r.get("apiKey"), r.get("key")):
                if r.get("status") in (None, "active", "enabled"):
                    cred = r
                    break
        if cred is None:
            _log("UNAUTHORIZED", {"rule": "invalid apiKey"}, apiKey)
            return _err("UNAUTHORIZED", "Invalid API key")
    else:
        # no credential store; accept any non-empty apiKey as a label
        cred = {"id": apiKey, "value": apiKey, "status": "active", "scopes": ["*"]}

    # compute simple usage snapshot from request_logs.json
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0)
    today = datetime.datetime.utcnow().date()

    rpm = 0
    today_count = 0
    for ev in logs:
        if ev.get("credential") != apiKey:
            continue
        ts = ev.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z","+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= one_min_ago:
                rpm += 1
            if dt.date() == today:
                today_count += 1

    _log("OK", {"cred_file": cred_file, "rpm_last_minute": rpm, "requests_today": today_count}, apiKey)
    return {
        "identity": {
            "apiKey": apiKey,
            "credential": cred,
        },
        "usage": {
            "requests_last_minute": rpm,
            "requests_today": today_count,
        },
    }
